-- Patch 1.8 (M30), generated by Supabase CLI 2.120.0 with bundled pg-delta.
-- npx.cmd --offline --no-install supabase db pull patch_1_8 --local --schema public,private --diff-engine pg-delta --yes
-- From tested supabase/sql/24-dungeons.sql on M01–M29; completed in dependency order.
-- Supabase applies this artifact in one transaction.

SET local check_function_bodies = off;

-- Reapplicable local source for Patch 1.8 (M30). Sections 1–3 admit, group, run and reveal v2 dungeon activities.
-- Planning keeps the account/receipt/character order and samples database time after the character lock.
-- Pair completion locks the job first and samples database time before checking the lease. Grouping's member
-- FKs then take KEY SHARE on preparing activities while phase 7 waits, as with Arena assignments.
-- Run seeds derive from the grouping job seed and run id. Phase 8 anchors the simulation to seat 0.
-- The shared reveal takes member activity KEY SHARE locks after its reveal-job lock. A member's
-- settlement uses only its own account, character, wallet, sorted items, activity and job locks, then samples time.
-- The run uses v2's 960000 ms fight interval, 120000 ms combat cap and 250 ms attack floor. Planning uses the v2
-- afternoon and levels 3/7/12.
-- 6B schema. Define the registry before the title and projection functions that read it.
-- The private catalog repeats the fixed v2 kits from domain/bots.ts. The routine seed is shared by every registration.
CREATE OR REPLACE FUNCTION private.bot_catalog()
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select jsonb_object_agg(member_key,jsonb_build_object(
    'key',member_key,'name',name,'level',level,'classId',class_id,'stance',stance,'role',role,
    'allocation',jsonb_build_object('strength',str,'agility',agi,'vitality',vit,'endurance',endurance,'precision',prec),
    'equipment',jsonb_build_object('weapon',weapon,'offHand',off_hand,'head',head,'body',body,'feet',feet),
    'earnedPoints',earned,'peakStrength',gear,'leagueIndex',league_index,'staminaMaximum',stamina,'league',league))
  from (values
    ('tullia','Tullia',12,'guardian','defensive','guard',10,0,18,7,3,
      'sword:10:common','round-shield:10:common','iron-helmet:10:common','light-armor:10:common','light-boots:10:common',38,84,39,115,'silver'),
    ('grit','Grit',7,'berserker','offensive','striker',13,2,7,0,3,
      'axe:5:common',null,'leather-hood:5:common','light-armor:5:common','light-boots:5:common',25,46.28,23,100,'bronze'),
    ('ash','Ash',7,'duelist','balanced','skirmisher',5,9,2,0,9,
      'sword:5:common',null,'leather-hood:5:common','light-armor:5:common','light-boots:5:common',25,48,23,100,'bronze'),
    ('rufus','Rufus',4,'guardian','defensive','guard',4,0,7,2,1,
      'sword:1:common','round-shield:1:common','iron-helmet:1:common','light-armor:1:common','light-boots:1:common',14,42,14,104,'bronze'),
    ('pip','Pip',3,'duelist','balanced','skirmisher',3,5,1,0,5,
      'sword:1:common',null,'leather-hood:1:common','light-armor:1:common','light-boots:1:common',14,32,11,100,'bronze')
  ) as kit(member_key,name,level,class_id,stance,role,str,agi,vit,endurance,prec,weapon,off_hand,head,body,feet,earned,gear,league_index,stamina,league)
$function$;
revoke all on function private.bot_catalog() from public,anon,authenticated,service_role;

create table if not exists private.bots (
  member_key text primary key check (private.bot_catalog() ? member_key),
  team text not null check (team='ludus-nimbus'),
  -- The trusted registry entry must exist before the gladiator's immediate Founder trigger runs.
  gladiator_id uuid not null unique references public.gladiators(id) deferrable initially deferred,
  role text not null check (role=private.bot_catalog()->member_key->>'role'),
  active boolean not null default false
);
create table if not exists private.bot_routines (
  member_key text not null check (private.bot_catalog() ? member_key),
  week_index smallint not null check (week_index between 0 and 125),
  directive text not null check (directive in ('off-duty','rest','on-call','arena','training')),
  primary key(member_key,week_index)
);
alter table private.bots enable row level security;
alter table private.bot_routines enable row level security;
revoke all on private.bots,private.bot_routines from public,anon,authenticated,service_role;
-- Only the private invoker coordinator needs the routine join, role and active flag. No API reader gets raw bot data.
grant select(gladiator_id,member_key,role,active) on private.bots to service_role;
grant select(member_key,week_index,directive) on private.bot_routines to service_role;
drop policy if exists backend_read on private.bots;
create policy backend_read on private.bots for select to service_role using (true);
drop policy if exists backend_read on private.bot_routines;
create policy backend_read on private.bot_routines for select to service_role using (true);

with weekly_slots as (
  select j as week_index,j%18 as day_slot,(j/18+(j%18-8)/3)%4 as pair_start
  from generate_series(0,125) slots(j)
), roster as (
  select member_key,array['grit','rufus','ash','pip'] as bronze from jsonb_object_keys(private.bot_catalog()) members(member_key)
)
insert into private.bot_routines as r(member_key,week_index,directive)
select member_key,week_index,case
  when day_slot<6 then 'off-duty'
  when day_slot%3=0 then 'rest'
  when day_slot%3=1 then 'on-call'
  when member_key in ('tullia',bronze[1+pair_start],bronze[1+(pair_start+1)%4]) then 'arena'
  else 'training' end
from weekly_slots cross join roster
on conflict(member_key,week_index) do update set directive=excluded.directive where r.directive<>excluded.directive;

-- 6C. Duty is frozen with the human cohort. Only the published processed slot feeds the actor projection.
create table if not exists private.bot_slot_duty (
  slot_index bigint not null check (slot_index>=0),
  gladiator_id uuid not null references private.bots(gladiator_id),
  directive text not null check (directive in ('off-duty','rest','on-call','arena','training')),
  role text not null check (role in ('guard','striker','skirmisher')),
  returns_at_ms bigint,
  primary key(slot_index,gladiator_id)
);
create index if not exists bot_slot_duty_gladiator_idx on private.bot_slot_duty(gladiator_id);
alter table private.bot_slot_duty drop constraint if exists bot_slot_duty_check,
  add constraint bot_slot_duty_check check (returns_at_ms is null or (directive='off-duty' and returns_at_ms>slot_index*4800000));
alter table private.bot_slot_duty enable row level security;
revoke all on private.bot_slot_duty from public,anon,authenticated,service_role;
grant select,insert on private.bot_slot_duty to service_role;
drop policy if exists backend_only on private.bot_slot_duty;
create policy backend_only on private.bot_slot_duty to service_role using (true) with check (true);
drop trigger if exists guard_frozen on private.bot_slot_duty;
create trigger guard_frozen before update on private.bot_slot_duty for each row execute function private.guard_frozen();

-- The coordinator holds the boundary lock. The duty table is append-only outside owner retention.
CREATE OR REPLACE FUNCTION private.freeze_bot_duty (
  target bigint
)
  RETURNS void
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  insert into private.bot_slot_duty(slot_index,gladiator_id,directive,role,returns_at_ms)
  select target,g.id,case when roster.on_duty then r.directive else 'off-duty' end,b.role,
    case when roster.on_duty and r.directive='off-duty' then (target-target%18+6)*4800000 end
  from private.boundaries boundary
  cross join private.bots b
  join public.gladiators g on g.id=b.gladiator_id
  join private.bot_routines r on r.member_key=b.member_key and r.week_index=((target-72)%126+126)%126
  cross join lateral (select b.active and boundary.rules_version='v2'
    and (select count(*) from private.boundary_members bm where bm.slot_index=target)<45 as on_duty) roster
  where boundary.slot_index=target and boundary.phase=3 and not boundary.members_frozen
    and g.processed_slot_index=target-1
  on conflict(slot_index,gladiator_id) do nothing
$function$;
revoke all on function private.freeze_bot_duty(bigint) from public,anon,authenticated,service_role;
grant execute on function private.freeze_bot_duty(bigint) to service_role;

-- SQL15 phases 3 and 8 retain the human idle recheck, account order and publication checkpoint.
CREATE OR REPLACE FUNCTION private.boundary_apply_changes (
  target bigint
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare b private.boundaries%rowtype; m record; starts_at bigint:=target*4800000;
  idle_ms bigint:=(private.idle_rules()->>'afterMs')::bigint;
begin
  select * into b from private.boundaries where slot_index=target for update;
  if not b.members_frozen then
    -- A never-started character whose creation committed after an earlier cohort froze joins this cohort; its
    -- orientation simply extends to this cutoff. A participating straggler is an inconsistency for the operator.
    for m in select g.id,g.owner_id from public.gladiators g where g.processed_slot_index<target-1
      and not exists(select 1 from public.activities a where a.gladiator_id=g.id) order by g.id loop
      perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,0));
      update public.gladiators set processed_slot_index=target-1,orientation_end_ms=target*4800000
        where id=m.id and processed_slot_index<target-1;
    end loop;
    if exists(select 1 from public.gladiators where processed_slot_index<target-1) then return 'straggler'; end if;
    -- Task 23.8: a character whose owner's last signal (or its creation, when later) is RULES_V1.idle before this boundary's
    -- scheduled start rests at home instead of joining the cohort. Each one the first read finds idle is read again under its
    -- owner's rate lock (consume_command_rate's), so a signal committed while the boundary waited counts.
    for m in select g.id,g.owner_id from public.gladiators g left join private.owner_signals s on s.owner_id=g.owner_id
      where g.processed_slot_index=target-1 and not exists(select 1 from private.bots bot where bot.gladiator_id=g.id)
        and starts_at-greatest(s.last_signal_ms,g.created_at_ms)>=idle_ms order by g.id loop
      perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,1));
      if (select starts_at-greatest(s.last_signal_ms,g.created_at_ms) from public.gladiators g
        left join private.owner_signals s on s.owner_id=g.owner_id where g.id=m.id)>=idle_ms then
        -- A rest that reached the previous slot continues; any other starts here, without a signal.
        insert into public.character_rests as r(gladiator_id,since_slot,through_slot,signalled_at_ms) values(m.id,target,target,null)
          on conflict (gladiator_id) do update set since_slot=case when r.through_slot=target-1 then r.since_slot else excluded.since_slot end,
            signalled_at_ms=case when r.through_slot=target-1 then r.signalled_at_ms end,through_slot=excluded.through_slot;
      end if;
    end loop;
    insert into private.boundary_members(slot_index,gladiator_id,owner_id)
      select target,g.id,g.owner_id from public.gladiators g where g.processed_slot_index=target-1
        and not exists(select 1 from private.bots bot where bot.gladiator_id=g.id)
        and not exists(select 1 from public.character_rests r where r.gladiator_id=g.id and r.through_slot=target)
      on conflict do nothing;
    perform private.freeze_bot_duty(target);
    insert into private.boundary_members(slot_index,gladiator_id,owner_id)
      select target,g.id,g.owner_id from private.bot_slot_duty d join public.gladiators g on g.id=d.gladiator_id
      where d.slot_index=target and d.directive<>'off-duty' on conflict do nothing;
    update private.boundaries set members_frozen=true,member_count=(select count(*) from private.boundary_members where slot_index=target)
      where slot_index=target;
  end if;
  for m in select bm.gladiator_id,bm.owner_id from private.boundary_members bm where bm.slot_index=target order by bm.gladiator_id loop
    perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,0));
    perform 1 from public.gladiators where id=m.gladiator_id for update;
    -- Repeat-safe: an already-applied or later-effective pending build returns false.
    perform private.apply_pending_build(m.gladiator_id,target);
  end loop;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION private.boundary_start (
  target bigint
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare a record; now_ms bigint:=private.planning_now_ms();
begin
  -- Check every member before any debit so an unsupported executor never leaves a partially started slot.
  if exists(select 1 from public.activities x where x.slot_index=target and x.status='preparing' and not private.activity_executor_ready(x.resolved_kind)) then
    return 'integration';
  end if;
  -- Exception 1: a member's jobs can reference another member's rows (an Arena battle job is anchored to side 0, whichever
  -- side comes first), so every account lock is held before the first such foreign key takes KEY SHARE on those rows.
  -- Task 23.8: the characters resting at this boundary take their account locks in the same gladiator-ordered pass.
  for a in select locked.owner_id from (
      select bm.gladiator_id,bm.owner_id from public.activities x
        join private.boundary_members bm on bm.slot_index=target and bm.gladiator_id=x.gladiator_id
        where x.slot_index=target and x.status='preparing'
      union all
      select g.id,g.owner_id from public.character_rests r join public.gladiators g on g.id=r.gladiator_id
        where r.through_slot=target and g.processed_slot_index=target-1
          and not exists(select 1 from private.bots b where b.gladiator_id=g.id)
      union all
      select g.id,g.owner_id from private.bot_slot_duty d join public.gladiators g on g.id=d.gladiator_id
        where d.slot_index=target and d.directive='off-duty' and g.processed_slot_index=target-1) locked
    order by locked.gladiator_id loop
    perform pg_advisory_xact_lock(hashtextextended(a.owner_id::text,0));
  end loop;
  for a in select x.id,x.gladiator_id,x.stamina_debit,x.debited,bm.owner_id from public.activities x
    join private.boundary_members bm on bm.slot_index=target and bm.gladiator_id=x.gladiator_id
    where x.slot_index=target and x.status='preparing' order by x.gladiator_id loop
    perform pg_advisory_xact_lock(hashtextextended(a.owner_id::text,0));
    perform 1 from public.gladiators where id=a.gladiator_id for update;
    if not a.debited then update public.gladiators set stamina_current=stamina_current-a.stamina_debit where id=a.gladiator_id; end if;
    perform private.prepare_activity_jobs(a.id);
    update public.activities set debited=true,status='active',published_at_ms=now_ms where id=a.id;
    update public.gladiators set processed_slot_index=target where id=a.gladiator_id and processed_slot_index=target-1;
  end loop;
  -- Task 23.8: a resting character's checkpoint advances with the cohort's.
  update public.gladiators g set processed_slot_index=target from public.character_rests r
    where r.gladiator_id=g.id and r.through_slot=target and g.processed_slot_index=target-1
      and not exists(select 1 from private.bots b where b.gladiator_id=g.id);
  update public.gladiators g set processed_slot_index=target from private.bot_slot_duty d
    where d.gladiator_id=g.id and d.slot_index=target and d.directive='off-duty' and g.processed_slot_index=target-1;
  return private.boundary_published(target);
end $function$;

-- SQL21 phases 4 and 5. Only human members enter ranked season ratings or read schedule revisions.
CREATE OR REPLACE FUNCTION private.boundary_recompute_leagues (
  target bigint
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare season bigint:=private.season_index(target); m record; g public.gladiators%rowtype; placed text; current_rating bigint;
begin
  if not exists(select 1 from private.boundary_members bm where bm.slot_index=target) then return null; end if;
  if season is null then return 'epoch'; end if;
  insert into public.seasons(season_index,starts_at_ms,ends_at_ms,rules_version)
    select season,b.starts_at_ms,b.ends_at_ms,(select frozen.rules_version from private.boundaries frozen where frozen.slot_index=target)
    from private.season_bounds(season) b
    on conflict do nothing;
  for m in select bm.gladiator_id,bm.owner_id,j.result->>'league' as computed,(j.result->>'arenaStrength')::numeric as strength
    from private.boundary_members bm join private.jobs j on j.dedupe_key='prepare:'||target||':'||bm.gladiator_id
    where bm.slot_index=target and not exists(select 1 from private.bots b where b.gladiator_id=bm.gladiator_id)
    order by bm.gladiator_id loop
    perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,0));
    select * into g from public.gladiators where id=m.gladiator_id for update;
    placed:=case when private.league_rank(m.computed)>private.league_rank(g.league) then m.computed else g.league end;
    insert into private.arena_ratings(gladiator_id,league,season_index) values(m.gladiator_id,placed,season) on conflict do nothing;
    select r.rating into current_rating from private.arena_ratings r
      where r.gladiator_id=m.gladiator_id and r.league=placed and r.season_index=season;
    if g.league is distinct from placed or g.rating is distinct from current_rating then
      update public.gladiators set league=placed,rating=current_rating where id=m.gladiator_id;
    end if;
    insert into public.public_profiles(gladiator_id,rating,combat_strength) values(m.gladiator_id,current_rating,m.strength)
      on conflict (gladiator_id) do update set combat_strength=excluded.combat_strength
      where public_profiles.combat_strength is distinct from excluded.combat_strength;
  end loop;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION private.boundary_snapshot (
  target bigint
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare b private.boundaries%rowtype; m record; g public.gladiators%rowtype; prep jsonb; preparation private.jobs%rowtype;
  schedule_version bigint; choice jsonb; activity uuid; bot_directive text;
begin
  select * into b from private.boundaries where slot_index=target;
  for m in select bm.gladiator_id,bm.owner_id from private.boundary_members bm where bm.slot_index=target
    and not exists(select 1 from public.activities a where a.gladiator_id=bm.gladiator_id and a.slot_index=target) order by bm.gladiator_id loop
    perform pg_advisory_xact_lock(hashtextextended(m.owner_id::text,0));
    select * into g from public.gladiators where id=m.gladiator_id for update;
    select j.* into preparation from private.jobs j where j.dedupe_key='prepare:'||target||':'||m.gladiator_id and j.status='completed';
    prep:=preparation.result;
    if b.rules_version='v2' and (preparation.rules_version is distinct from b.rules_version
      or preparation.slot_index is distinct from target or not private.valid_preparation(preparation.id,prep)) then
      raise exception 'invalid boundary preparation';
    end if;
    select d.directive into bot_directive from private.bot_slot_duty d where d.slot_index=target and d.gladiator_id=m.gladiator_id;
    if bot_directive is null then
      -- Historical authority: latest revision effective by this slot, never the mutable latest-plan row.
      select r.version,r.choice into schedule_version,choice from public.schedule_revisions r where r.gladiator_id=m.gladiator_id
        and r.phase=private.slot_phase(target) and r.effective_slot_index<=target order by r.effective_slot_index desc,r.version desc limit 1;
    else
      -- Bot Arena intent resolves with the same affordability check, outside the human pairing pool.
      schedule_version:=1;
      choice:=jsonb_build_object('kind',case when bot_directive in ('on-call','training') then 'training'
        when bot_directive='arena' then 'arena' else 'rest' end);
    end if;
    if schedule_version is null or prep is null then raise exception 'missing boundary input'; end if;
    insert into public.activities(gladiator_id,slot_index,starts_at_ms,ends_at_ms,requested,schedule_version,status)
      values(m.gladiator_id,target,target*4800000,(target+1)*4800000,choice,schedule_version,'preparing') returning id into activity;
    insert into private.activity_snapshots(activity_id,snapshot,seed,rules_version) values(activity,jsonb_build_object(
      'activityId',activity,'gladiatorId',m.gladiator_id,'slotIndex',target,'rulesVersion',b.rules_version,'cutoffMs',b.cutoff_ms,
      'choice',choice,'scheduleVersion',schedule_version,'build',prep->'snapshot','derived',prep->'derived','costs',prep->'costs',
      'trainingPoints',prep->'trainingPoints','starting',jsonb_build_object(
        'stamina',jsonb_build_object('current',g.stamina_current,'maximum',g.stamina_maximum),'level',g.level,'xp',g.xp,
        'earnedPoints',g.earned_points,'unspentPoints',g.unspent_points,'league',g.league,'rating',g.rating,
        'peakStrength',g.peak_strength,'tournamentOptIn',g.tournament_opt_in))
      ||case when b.rules_version='v2' then jsonb_build_object('trainingAllowed',prep->'trainingAllowed') else '{}'::jsonb end
      ||case when bot_directive is not null then jsonb_build_object('botDirective',bot_directive) else '{}'::jsonb end
      ||case when bot_directive='arena' then jsonb_build_object('botArena',jsonb_build_object('name',g.name,
        'snapshot',prep->'arenaFighter','strengthCents',(prep->>'arenaStrength')::numeric*100)) else '{}'::jsonb end,
      encode(extensions.gen_random_bytes(32),'hex'),b.rules_version);
  end loop;
  return null;
end $function$;

-- 1. Planning and affordability. Old workers can still send the five-key preparation under either retained version.
alter table public.activities drop constraint if exists activities_resolved_kind_check,
  add constraint activities_resolved_kind_check check (resolved_kind in ('training','rest','expedition','arena','tournament','dungeon'));

CREATE OR REPLACE FUNCTION private.planning_command (
  actor_id     uuid,
  operation_id uuid,
  input        jsonb,
  kind         text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare c jsonb:=input->'command'; prep jsonb:=input->'prepared'; prior public.operation_receipts%rowtype;
  g public.gladiators%rowtype; b public.builds%rowtype; s public.schedules%rowtype;
  now_ms bigint; slot bigint; receipt uuid:=gen_random_uuid(); result jsonb; err text; fee bigint; available bigint;
  inventory jsonb; ids jsonb; next_build jsonb; effective bigint; next_version bigint; required_level integer;
  part record; parts jsonb; next_schedule jsonb;
begin
  if actor_id is null then return jsonb_build_object('ok',false,'code','unauthenticated'); end if;
  if operation_id is null or jsonb_typeof(c) is distinct from 'object' then return jsonb_build_object('ok',false,'code','invalid'); end if;
  perform pg_advisory_xact_lock(hashtextextended(actor_id::text,0));
  select * into prior from public.operation_receipts r where r.owner_id=actor_id and r.operation_id=planning_command.operation_id;
  if found then
    if prior.request<>c then return jsonb_build_object('ok',false,'code','conflict'); end if;
    return prior.result;
  end if;
  if c->>'kind' is distinct from kind or c->>'operationId' is distinct from operation_id::text
    or jsonb_typeof(c->'expectedVersion') is distinct from 'number' then return jsonb_build_object('ok',false,'code','invalid'); end if;
  if (c->>'expectedVersion')::numeric not between 1 and 9007199254740991 or trunc((c->>'expectedVersion')::numeric)<>(c->>'expectedVersion')::numeric
    then return jsonb_build_object('ok',false,'code','invalid'); end if;
  select * into g from public.gladiators where owner_id=actor_id for update;
  if not found then return jsonb_build_object('ok',false,'code','not-found'); end if;
  now_ms:=private.planning_now_ms(); slot:=now_ms/4800000;
  -- A transient processing result is not retained: this exact operation may succeed after catch-up.
  if g.processed_slot_index<slot then return jsonb_build_object('ok',false,'code','processing','retryAfterMs',1000); end if;
  select * into b from public.builds where gladiator_id=g.id for update;
  select * into s from public.schedules where gladiator_id=g.id for update;
  perform 1 from public.wallets where gladiator_id=g.id for update;
  perform 1 from public.item_instances where gladiator_id=g.id order by id for update;
  if (c->>'expectedVersion')::bigint <> (case when kind in ('edit-schedule','edit-day-schedule') then s.version else b.version end) then err:='conflict';
  elsif kind='edit-schedule' then
    if (select count(*) from jsonb_object_keys(c))<>5 or not(c ?& array['kind','operationId','expectedVersion','phase','choice'])
      or c->>'phase' is null or c->>'phase' not in ('morning','afternoon','evening') or jsonb_typeof(c->'choice') is distinct from 'object' then err:='invalid';
    -- Arena only in the evening (RULES_V1.schedule.arenaPhases).
    elsif c->'choice'->>'kind'='arena' and c->>'phase'<>'evening' then err:='invalid';
    elsif c->'choice'->>'kind' in ('rest','training','arena') and (select count(*) from jsonb_object_keys(c->'choice'))=1 then null;
    elsif c->'choice'->>'kind'='expedition' and (select count(*) from jsonb_object_keys(c->'choice'))=2 and c->'choice' ? 'expeditionId' then
      required_level:=case c->'choice'->>'expeditionId' when 'woodland' then 1 when 'outpost' then 5 when 'mountain' then 10 else null end;
      if required_level is null or g.level<required_level then err:='invalid'; end if;
    elsif c->'choice'->>'kind'='dungeon' and (select count(*) from jsonb_object_keys(c->'choice'))=2 and c->'choice' ? 'dungeonId' then
      required_level:=case c->'choice'->>'dungeonId' when 'wolf-den' then 3 when 'raider-stronghold' then 7 when 'troll-hall' then 12 end;
      if c->>'phase'<>'afternoon' or private.active_rules_version() is distinct from 'v2'
        or required_level is null or g.level<required_level then err:='invalid'; end if;
    else err:='invalid'; end if;
    if err is null then
      effective:=private.schedule_effective_slot(c->>'phase',now_ms); next_version:=s.version+1;
      update public.schedules set version=next_version,schedule=jsonb_set(schedule,array[c->>'phase'],c->'choice') where gladiator_id=g.id;
      insert into public.schedule_revisions values(g.id,next_version,c->>'phase',c->'choice',now_ms,effective);
      result:=jsonb_build_object('version',next_version,'receivedAtMs',now_ms,'effectiveSlotIndex',effective,'effectiveAtMs',effective*4800000);
    end if;
  elsif kind='edit-day-schedule' then
    if (select count(*) from jsonb_object_keys(c))<>4 or not(c ?& array['kind','operationId','expectedVersion','day'])
      or jsonb_typeof(c->'day') is distinct from 'object' then err:='invalid';
    elsif (select count(*) from jsonb_object_keys(c->'day'))<>3 or not(c->'day' ?& array['morning','afternoon','evening']) then err:='invalid';
    else
      -- Each part's choice exactly as edit-schedule checks one; any refused part refuses the whole day.
      for part in select e.key as phase,e.value as choice from jsonb_each(c->'day') e loop
        if jsonb_typeof(part.choice) is distinct from 'object' then err:='invalid';
        elsif part.choice->>'kind'='arena' and part.phase<>'evening' then err:='invalid';
        elsif part.choice->>'kind' in ('rest','training','arena') and (select count(*) from jsonb_object_keys(part.choice))=1 then null;
        elsif part.choice->>'kind'='expedition' and (select count(*) from jsonb_object_keys(part.choice))=2 and part.choice ? 'expeditionId' then
          required_level:=case part.choice->>'expeditionId' when 'woodland' then 1 when 'outpost' then 5 when 'mountain' then 10 else null end;
          if required_level is null or g.level<required_level then err:='invalid'; end if;
        elsif part.choice->>'kind'='dungeon' and (select count(*) from jsonb_object_keys(part.choice))=2 and part.choice ? 'dungeonId' then
          required_level:=case part.choice->>'dungeonId' when 'wolf-den' then 3 when 'raider-stronghold' then 7 when 'troll-hall' then 12 end;
          if part.phase<>'afternoon' or private.active_rules_version() is distinct from 'v2'
            or required_level is null or g.level<required_level then err:='invalid'; end if;
        else err:='invalid'; end if;
      end loop;
      -- A day with no change is invalid (values are compared, not their key order).
      if err is null and not exists(select 1 from jsonb_each(c->'day') e where e.value is distinct from s.schedule->e.key) then err:='invalid'; end if;
    end if;
    if err is null then
      -- One version for the day; a revision, at its own next occurrence, only for each part whose choice changes.
      next_version:=s.version+1; next_schedule:=s.schedule; parts:='{}'::jsonb;
      for part in select p.phase,c->'day'->p.phase as choice from unnest(array['morning','afternoon','evening']) with ordinality p(phase,n) order by p.n loop
        if part.choice is distinct from s.schedule->part.phase then
          effective:=private.schedule_effective_slot(part.phase,now_ms);
          next_schedule:=jsonb_set(next_schedule,array[part.phase],part.choice);
          insert into public.schedule_revisions values(g.id,next_version,part.phase,part.choice,now_ms,effective);
          parts:=parts||jsonb_build_object(part.phase,jsonb_build_object('effectiveSlotIndex',effective,'effectiveAtMs',effective*4800000));
        else
          parts:=parts||jsonb_build_object(part.phase,null);
        end if;
      end loop;
      update public.schedules set version=next_version,schedule=next_schedule where gladiator_id=g.id;
      result:=jsonb_build_object('version',next_version,'receivedAtMs',now_ms,'parts',parts);
    end if;
  elsif kind='queue-build' then
    if prep is null or prep='null'::jsonb then err:='invalid';
    else
      select coalesce(jsonb_agg(item order by id),'[]'::jsonb) into inventory from public.item_instances where gladiator_id=g.id;
      if prep->'baseline' is distinct from jsonb_build_object('currentBuild',b.current_build,'pendingBuild',b.pending_build,'buildVersion',b.version,
        'earnedPoints',g.earned_points,'level',g.level,'inventory',inventory) then err:='conflict';
      else
        fee:=(prep->>'fee')::bigint;
        select w.money-coalesce((select sum(r.money) from public.reservations r where r.gladiator_id=g.id and r.status='held'
          and r.operation_id is distinct from (b.pending_build->>'operationId')::uuid),0) into available from public.wallets w where w.gladiator_id=g.id;
        -- Fixed class and points: the class and every attribute are compared to the CURRENT build (b.current_build), never to the
        -- pending one, so a pending build may still be revised down to the current values (not below) and cancelled.
        if c->>'classId' is distinct from b.current_build->>'classId'
          or exists(select 1 from jsonb_each(b.current_build->'allocations') a where jsonb_typeof(c->'allocation'->a.key) is distinct from 'number' or (c->'allocation'->a.key) < a.value) then err:='invalid';
        -- No build change costs gold any more (it was fee not in (0,100,200)); a null fee is refused too.
        elsif fee is distinct from 0 then err:='invalid';
        elsif available<fee then err:='insufficient-funds'; end if;
      end if;
    end if;
    if err is null then
      next_version:=b.version+1; effective:=slot+1;
      next_build:=jsonb_build_object('version',next_version,'classId',c->'classId','stance',c->'stance','allocations',c->'allocation','equipment',c->'equipment');
      select coalesce(jsonb_agg(value order by value),'[]'::jsonb) into ids from jsonb_each(c->'equipment') where value<>'null'::jsonb;
      update public.reservations r set status='refunded' where r.gladiator_id=g.id and r.operation_id=(b.pending_build->>'operationId')::uuid and r.status='held';
      delete from public.pending_build_items where gladiator_id=g.id;
      update public.item_instances set item=jsonb_set(item,'{reservation}','null') where gladiator_id=g.id and item->'reservation'->>'kind'='pending-build';
      insert into public.reservations(gladiator_id,operation_id,money,status) values(g.id,planning_command.operation_id,fee,'held');
      insert into public.pending_build_items select value::text::uuid,g.id,planning_command.operation_id from jsonb_array_elements_text(ids);
      update public.item_instances set item=jsonb_set(item,'{reservation}',jsonb_build_object('kind','pending-build','referenceId',planning_command.operation_id))
        where gladiator_id=g.id and id in (select item_id from public.pending_build_items where gladiator_id=g.id) and item->'reservation'='null'::jsonb;
      result:=jsonb_build_object('build',next_build,'effectiveSlotIndex',effective,'reservedMoney',fee,'reservedItemIds',ids,'operationId',operation_id);
      update public.builds set version=next_version,pending_build=result where gladiator_id=g.id;
      insert into private.pending_build_preparations values(g.id,operation_id,prep->'snapshot',(prep->>'staminaMaximum')::bigint,now_ms)
        on conflict(gladiator_id) do update set operation_id=excluded.operation_id,snapshot=excluded.snapshot,stamina_maximum=excluded.stamina_maximum,received_at_ms=excluded.received_at_ms;
    end if;
  elsif kind='cancel-build' then
    if (select count(*) from jsonb_object_keys(c))<>3 then err:='invalid';
    else
      update public.reservations r set status='refunded' where r.gladiator_id=g.id and r.operation_id=(b.pending_build->>'operationId')::uuid and r.status='held';
      delete from public.pending_build_items where gladiator_id=g.id;
      update public.item_instances set item=jsonb_set(item,'{reservation}','null') where gladiator_id=g.id and item->'reservation'->>'kind'='pending-build';
      delete from private.pending_build_preparations where gladiator_id=g.id;
      update public.builds set version=version+1,pending_build=null where gladiator_id=g.id;
      result:=jsonb_build_object('buildVersion',b.version+1);
    end if;
  else err:='invalid'; end if;
  result:=case when err is null then jsonb_build_object('ok',true,'receiptId',receipt,'value',result) else jsonb_build_object('ok',false,'code',err) end;
  insert into public.operation_receipts(owner_id,operation_id,receipt_id,gladiator_id,request,request_digest,result)
    values(actor_id,operation_id,receipt,g.id,c,sha256(convert_to(c::text,'UTF8')),result);
  return result;
end $function$;

CREATE OR REPLACE FUNCTION private.valid_preparation (
  job    uuid,
  result jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare j private.jobs%rowtype; k text; v jsonb;
begin
  select * into j from private.jobs where id=job;
  if not found then return false; end if;
  if jsonb_typeof(result) is distinct from 'object' or result->>'rulesVersion' is distinct from j.rules_version
    or jsonb_typeof(result->'snapshot') is distinct from 'object' or jsonb_typeof(result->'derived') is distinct from 'object'
    or jsonb_typeof(result->'costs') is distinct from 'object' then return false; end if;
  -- Type guards precede enumeration and casts; SQL expression evaluation order is not a validation boundary.
  if result->'costs' ? 'dungeon' then
    if j.rules_version is distinct from 'v2' or (select count(*) from jsonb_object_keys(result->'costs'))<>6
      or not private.safe_integer(result->'costs'->'dungeon') then return false; end if;
  elsif (select count(*) from jsonb_object_keys(result->'costs'))<>5 then return false;
  end if;
  if j.rules_version='v2' then
    if not private.safe_integer(to_jsonb(j.slot_index)) or not private.safe_integer(j.input->'slotIndex')
      or not private.safe_integer(j.input->'trainingActivitiesEarlierInDay')
      or jsonb_typeof(result->'trainingAllowed') is distinct from 'boolean' then return false; end if;
    -- Integral JSON numbers can retain decimal spelling (301.0); numeric preserves safe_integer's accepted domain.
    if (j.input->>'slotIndex')::numeric<>j.slot_index
      or (j.input->>'trainingActivitiesEarlierInDay')::numeric>j.slot_index%3 then return false; end if;
    if result->'trainingAllowed' is distinct from to_jsonb((j.input->>'trainingActivitiesEarlierInDay')::numeric<2) then return false; end if;
  end if;
  foreach k in array array['training','rest','expedition','arena','tournament'] loop
    v:=result->'costs'->k;
    if jsonb_typeof(v) is distinct from 'number' then return false; end if;
    if v::text::numeric not between 0 and 9007199254740991 or trunc(v::text::numeric)<>v::text::numeric then return false; end if;
  end loop;
  if (result->'costs'->>'rest')::numeric<>0 or jsonb_typeof(result->'trainingPoints') is distinct from 'number'
    or jsonb_typeof(result->'staminaMaximum') is distinct from 'number' then return false; end if;
  if (result->>'trainingPoints')::numeric not between 0 and 1000000000 or trunc((result->>'trainingPoints')::numeric)<>(result->>'trainingPoints')::numeric
    or (result->>'staminaMaximum')::numeric not between 1 and 9007199254740991
    or trunc((result->>'staminaMaximum')::numeric)<>(result->>'staminaMaximum')::numeric then return false; end if;
  if result->'snapshot'->>'rulesVersion' is distinct from j.rules_version or result->'snapshot'->>'classId' is distinct from j.input->'build'->>'classId'
    or result->'snapshot'->>'stance' is distinct from j.input->'build'->>'stance'
    or result->'snapshot'->'allocations' is distinct from j.input->'build'->'allocations' then return false; end if;
  foreach k in array array['weapon','offHand','head','body','feet'] loop
    if result->'snapshot'->'equipment'->k->>'id' is distinct from j.input->'build'->'equipment'->>k then return false; end if;
  end loop;
  if result->'league' is null or result->'league' not in ('"bronze"'::jsonb,'"silver"'::jsonb,'"gold"'::jsonb,'"champion"'::jsonb)
    or jsonb_typeof(result->'arenaStrength') is distinct from 'number' then return false; end if;
  if (result->>'arenaStrength')::numeric not between 0 and 9007199254740991
    or trunc((result->>'arenaStrength')::numeric*100)<>(result->>'arenaStrength')::numeric*100 then return false; end if;
  if jsonb_typeof(result->'arenaFighter') is distinct from 'object' or jsonb_typeof(result->'npcTemplate') is distinct from 'object'
    or result->'arenaFighter'->>'rulesVersion' is distinct from j.rules_version or result->'npcTemplate'->>'rulesVersion' is distinct from j.rules_version
    or result->'arenaFighter'->>'classId' is distinct from j.input->'build'->>'classId'
    or result->'arenaFighter'->>'stance' is distinct from j.input->'build'->>'stance'
    or result->'npcTemplate'->'classId' is distinct from 'null'::jsonb or result->'npcTemplate'->>'stance' is distinct from 'balanced' then return false; end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION private.boundary_check_stamina (
  target bigint
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  -- Reject a malformed immutable v2 snapshot before pricing casts or any activity write. Historical v1 omits this field.
  if exists(select 1 from public.activities a join private.activity_snapshots s on s.activity_id=a.id
    where a.slot_index=target and a.status='preparing' and a.resolved_kind is null and s.rules_version='v2'
      and jsonb_typeof(s.snapshot->'trainingAllowed') is distinct from 'boolean') then
    raise exception 'invalid Training allowance snapshot';
  end if;
  with chosen as (
    select a.id,s.snapshot,s.rules_version,case when s.rules_version='v2' and a.requested->>'kind'='training'
      and s.snapshot->'trainingAllowed'='false'::jsonb then 'rest' else a.requested->>'kind' end as kind
    from public.activities a join private.activity_snapshots s on s.activity_id=a.id
    where a.slot_index=target and a.status='preparing' and a.resolved_kind is null
  ), priced as (
    -- A validated v2 cost can have an integral decimal spelling (40.0). Keep historical v1 pricing unchanged.
    select c.id,c.kind,case when c.rules_version='v2' then (c.snapshot->'costs'->>c.kind)::numeric::bigint
      when c.kind<>'dungeon' then (c.snapshot->'costs'->>c.kind)::bigint end as cost,
      (c.snapshot->'starting'->'stamina'->>'current')::bigint as stamina
    from chosen c
  ), resolved as (
    select p.*,case when p.kind='dungeon' and p.cost is null then true else p.cost>p.stamina end as fallback from priced p
  )
  update public.activities a set resolved_kind=case when r.fallback then 'rest' else r.kind end,
    fallback=r.fallback,stamina_debit=case when r.fallback then 0 else r.cost end
  from resolved r where r.id=a.id;
  return null;
end $function$;

-- 2. Phase 7. Each dungeon's pair job owns its frozen cohort and every accepted run has exactly one row per human seat.
create table if not exists private.dungeon_runs (
  run_id text primary key,
  grouping_job_id uuid not null references private.jobs(id),
  slot_index bigint not null check (slot_index >= 0),
  dungeon_id text not null check (dungeon_id in ('wolf-den','raider-stronghold','troll-hall')),
  seed text not null,
  assignment jsonb not null check (jsonb_typeof(assignment)='object'),
  created_at_ms bigint not null,
  check (run_id ~ ('^dungeon:'||slot_index||':'||dungeon_id||':[1-9][0-9]*$'))
);
create index if not exists dungeon_runs_grouping_job_idx on private.dungeon_runs(grouping_job_id);
create index if not exists dungeon_runs_slot_idx on private.dungeon_runs(slot_index);

create table if not exists private.dungeon_run_members (
  activity_id uuid primary key references public.activities(id),
  run_id text not null references private.dungeon_runs(run_id),
  seat smallint not null check (seat between 0 and 2),
  unique (run_id,seat)
);

alter table private.dungeon_runs enable row level security;
alter table private.dungeon_run_members enable row level security;
revoke all on private.dungeon_runs,private.dungeon_run_members from public,anon,authenticated,service_role;
grant select,insert,delete on private.dungeon_runs,private.dungeon_run_members to service_role;
drop policy if exists backend_only on private.dungeon_runs;
create policy backend_only on private.dungeon_runs to service_role using (true) with check (true);
drop policy if exists backend_only on private.dungeon_run_members;
create policy backend_only on private.dungeon_run_members to service_role using (true) with check (true);
drop trigger if exists guard_frozen on private.dungeon_runs;
create trigger guard_frozen before update on private.dungeon_runs for each row execute function private.guard_frozen();
drop trigger if exists guard_frozen on private.dungeon_run_members;
create trigger guard_frozen before update on private.dungeon_run_members for each row execute function private.guard_frozen();

CREATE OR REPLACE FUNCTION private.grouping_input (
  target  bigint,
  dungeon text,
  rules   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('kind','dungeon-grouping','slotIndex',target,'dungeonId',dungeon,'rulesVersion',rules,
    'entrants',coalesce(jsonb_agg(jsonb_build_object('gladiatorId',a.gladiator_id,'activityId',a.id,'name',g.name,
      'level',s.snapshot->'starting'->'level','build',s.snapshot->'build') order by a.gladiator_id),'[]'::jsonb))
  from public.activities a join private.activity_snapshots s on s.activity_id=a.id
    join public.gladiators g on g.id=a.gladiator_id
  where a.slot_index=target and a.status='preparing' and a.resolved_kind='dungeon'
    and a.requested->>'kind'='dungeon' and a.requested->>'dungeonId'=dungeon and s.rules_version=rules
$function$;

-- 6D. The unique slot reservation is attached to the accepted assignment. Last meetings outlive replay cleanup.
alter table private.arena_assignments drop constraint if exists arena_assignments_kind_check,
  add constraint arena_assignments_kind_check check (kind in ('human','npc','bot')
    and (kind<>'bot' or jsonb_typeof(assignment->'opponent'->'id') is not distinct from 'string'));
create unique index if not exists arena_one_bot_per_slot on private.arena_assignments(slot_index,((assignment->'opponent'->>'id')::uuid))
  where kind='bot';

create table if not exists private.bot_arena_history (
  human_id uuid not null references public.gladiators(id) on delete cascade,
  bot_id uuid not null references private.bots(gladiator_id) on delete cascade,
  last_slot bigint not null check (last_slot>=0),
  primary key(human_id,bot_id),
  check (human_id<>bot_id)
);
create index if not exists bot_arena_history_bot_idx on private.bot_arena_history(bot_id);
alter table private.bot_arena_history enable row level security;
revoke all on private.bot_arena_history from public,anon,authenticated,service_role;
grant select,insert,update on private.bot_arena_history to service_role;
drop policy if exists backend_only on private.bot_arena_history;
create policy backend_only on private.bot_arena_history to service_role using (true) with check (true);

-- SQL09 pairing input retains the old worker wire. Bot duties have no tournament candidacy or history here.
CREATE OR REPLACE FUNCTION private.pairing_input (
  target    bigint,
  league_id text,
  season    bigint,
  rules     text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with requested as (
    select a.id as activity_id,a.gladiator_id,a.resolved_kind,s.snapshot,jsonb_build_object('gladiatorId',a.gladiator_id,'activityId',a.id,
      'seasonId',season::text,'league',league_id,'slotIndex',target,'rating',s.snapshot->'starting'->'rating','fighter',p.result->'arenaFighter') as entrant
    from public.activities a join private.activity_snapshots s on s.activity_id=a.id
    join private.jobs p on p.dedupe_key='prepare:'||target||':'||a.gladiator_id and p.status='completed'
    where a.slot_index=target and a.status='preparing' and a.requested->>'kind'='arena' and a.resolved_kind in ('arena','rest')
      and not (s.snapshot ? 'botDirective') and s.snapshot->'starting'->>'league'=league_id),
  entrants as (select * from requested where resolved_kind='arena'),
  history as (
    select x.slot_index,x.battle_id as id,x.assignment->'sides'->0->>'gladiatorId' as a,x.assignment->'sides'->1->>'gladiatorId' as b
    from private.jobs pj join private.arena_assignments x on x.pairing_job_id=pj.id
    where pj.kind='pair' and pj.slot_index between target-18 and target-1 and x.kind='human'
    union all
    select t.slot_index,o.id,case when o.round=1 then o.placed->>0 else o.result->>'winnerId' end,
      case when o.round=1 then o.placed->>1 else o.result->>'loserId' end
    from private.tournaments t join private.tournament_bouts o on o.tournament_id=t.id
    where t.slot_index between target-18 and target-1 and not o.bye)
  select jsonb_build_object('slotIndex',target,'league',league_id,'seasonId',season::text,'rulesVersion',rules,'historyFromSlot',target-18,
    'entrants',coalesce((select jsonb_agg(e.entrant order by e.gladiator_id) from entrants e),'[]'::jsonb),
    'recent',coalesce((select jsonb_agg(jsonb_build_object('slotIndex',h.slot_index,'gladiatorIds',jsonb_build_array(h.a,h.b)) order by h.slot_index,h.id)
      from history h where h.a in (select e.gladiator_id::text from entrants e) and h.b in (select e.gladiator_id::text from entrants e)),'[]'::jsonb),
    'tournament',jsonb_build_object(
      'rested',coalesce((select jsonb_agg(r.entrant order by r.gladiator_id) from requested r where r.resolved_kind='rest'),'[]'::jsonb),
      'candidates',coalesce((select jsonb_agg(jsonb_build_object('gladiatorId',r.gladiator_id,'choice',r.snapshot->'choice',
        'stamina',r.snapshot->'starting'->'stamina'->'current',
        'costs',jsonb_build_object('arena',r.snapshot->'costs'->'arena','tournament',r.snapshot->'costs'->'tournament'),
        'optIn',jsonb_build_array(jsonb_build_object('enabled',r.snapshot->'starting'->'tournamentOptIn','receivedAtMs',target*4800000-1)))
        order by r.gladiator_id) from requested r),'[]'::jsonb)))
$function$;

-- SQL21 validation is retained in full before an NPC fallback can be substituted.
CREATE OR REPLACE FUNCTION private.accept_pairing (
  job    uuid,
  result jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare j private.jobs%rowtype; frozen jsonb; expected jsonb; bracketed jsonb:='{}'::jsonb; routed jsonb:='{}'::jsonb; seen jsonb:='{}'::jsonb;
  e jsonb; s jsonb; x jsonb; r jsonb; gid text; human boolean; keys text[]; sides integer; league_id text; season bigint;
  now_ms bigint:=private.planning_now_ms(); partitioned boolean; bracket jsonb; tid text;
  opponent jsonb; human_strength_cents numeric;
  eligible jsonb:='{}'::jsonb; has_bracket boolean:=false; calendar boolean; required_route text; required_reason text;
begin
  select * into j from private.jobs where id=job;
  partitioned:=j.input ? 'tournament';
  keys:=case when partitioned then array['assignments','tournament'] else array['assignments'] end;
  if j.kind is distinct from 'pair' or jsonb_typeof(result) is distinct from 'object' or jsonb_typeof(result->'assignments') is distinct from 'array'
    or (select array_agg(k order by k collate "C") from jsonb_object_keys(result) k) is distinct from keys then return false; end if;
  league_id:=j.input->>'league';
  season:=private.season_index(j.slot_index);
  if season is null or j.input->>'seasonId' is distinct from season::text then return false; end if;
  -- The frozen values of every Arena request of this slot and league: resolved Arena, or Rest by step 6.
  select coalesce(jsonb_object_agg(a.gladiator_id::text,jsonb_build_object('activityId',a.id,'kind',a.resolved_kind,
      'rating',sn.snapshot->'starting'->'rating','strength',p.result->'arenaStrength','fighter',p.result->'arenaFighter','npc',p.result->'npcTemplate',
      'costs',sn.snapshot->'costs','snapshot',sn.snapshot,'requested',a.requested,'snapshotVersion',sn.rules_version,
      'preparationVersion',p.rules_version,'preparationResultVersion',p.result->'rulesVersion',
      'preparationSlot',p.slot_index,'preparationInputSlot',p.input->'slotIndex')),'{}'::jsonb) into frozen
    from public.activities a join private.activity_snapshots sn on sn.activity_id=a.id
    join private.jobs p on p.dedupe_key='prepare:'||a.slot_index||':'||a.gladiator_id and p.status='completed'
    where a.slot_index=j.slot_index and a.status='preparing' and a.requested->>'kind'='arena' and a.resolved_kind in ('arena','rest')
      and not (sn.snapshot ? 'botDirective') and sn.snapshot->'starting'->>'league'=league_id;
  select coalesce(jsonb_object_agg(f.key,f.value),'{}'::jsonb) into expected from jsonb_each(frozen) f where f.value->>'kind'='arena';
  if j.rules_version='v2' then
    if not partitioned or not private.safe_integer(to_jsonb(j.slot_index)) then return false; end if;
    -- The frozen pool and cutoff opt-in must agree with the job that the worker actually received. This reconstructs
    -- only private frozen activity/preparation data, never the character's current opt-in or latest schedule.
    if j.input is distinct from jsonb_set(private.pairing_input(j.slot_index,league_id,season,j.rules_version),
      '{tournament,bracketSeed}',to_jsonb(encode(extensions.digest(j.seed||':bracket','sha256'),'hex'))) then return false; end if;
    calendar:=private.economy_tournament_slot(j.slot_index);
    for gid,x in select key,value from jsonb_each(frozen) loop
      if x->'snapshotVersion' is distinct from '"v2"'::jsonb or x->'preparationVersion' is distinct from '"v2"'::jsonb
        or x->'preparationResultVersion' is distinct from '"v2"'::jsonb or x->'fighter'->'rulesVersion' is distinct from '"v2"'::jsonb
        or x->'preparationSlot' is distinct from to_jsonb(j.slot_index) or x->'preparationInputSlot' is distinct from to_jsonb(j.slot_index)
        or x->'snapshot'->'rulesVersion' is distinct from '"v2"'::jsonb
        or x->'snapshot'->'slotIndex' is distinct from to_jsonb(j.slot_index)
        or x->'snapshot'->'cutoffMs' is distinct from to_jsonb(j.slot_index*4800000)
        or x->'snapshot'->'activityId' is distinct from x->'activityId'
        or x->'snapshot'->'gladiatorId' is distinct from to_jsonb(gid)
        or x->'snapshot'->'choice' is distinct from x->'requested'
        or x->'snapshot'->'choice'->>'kind' is distinct from 'arena'
        or x->'snapshot'->'starting'->'league' is distinct from to_jsonb(league_id)
        or jsonb_typeof(x->'snapshot'->'starting'->'tournamentOptIn') is distinct from 'boolean'
        or not private.safe_integer(x->'snapshot'->'starting'->'stamina'->'current')
        or not private.safe_integer(x->'costs'->'arena') or x->'costs'->'tournament' is distinct from '0'::jsonb then return false; end if;
      -- Validate numeric types above before casting. Whole-number JSON spellings such as 25.0 remain valid.
      if (x->>'kind'='arena') is distinct from
        ((x->'snapshot'->'starting'->'stamina'->>'current')::numeric >= (x->'costs'->>'arena')::numeric) then return false; end if;
      if calendar and x->'snapshot'->'starting'->'tournamentOptIn'='true'::jsonb then
        eligible:=eligible||jsonb_build_object(gid,true);
      end if;
    end loop;
    has_bracket:=(select count(*) from jsonb_object_keys(eligible))>=2;
  end if;
  if partitioned then
    if jsonb_typeof(result->'tournament') is distinct from 'object'
      or (select array_agg(k order by k collate "C") from jsonb_object_keys(result->'tournament') k) is distinct from array['bracket','routes']
      or jsonb_typeof(result->'tournament'->'routes') is distinct from 'array' then return false; end if;
    for r in select value from jsonb_array_elements(result->'tournament'->'routes') loop
      if jsonb_typeof(r) is distinct from 'object'
        or (select array_agg(k order by k collate "C") from jsonb_object_keys(r) k)
          is distinct from array['activityId','gladiatorId','league','reason','route','staminaDebit']
        or jsonb_typeof(r->'gladiatorId') is distinct from 'string' then return false; end if;
      gid:=r->>'gladiatorId'; x:=frozen->gid;
      if x is null or routed ? gid or r->'activityId' is distinct from x->'activityId' or r->'league' is distinct from to_jsonb(league_id)
        then return false; end if;
      if j.rules_version='v2' then
        -- Derive the required route from the complete eligible pool: a valid smaller bracket, or all-Rest suppression,
        -- is still invalid. Non-bracket entrants retain the preliminary ordinary-Arena affordability decision.
        required_route:=case when has_bracket and eligible ? gid then 'tournament' else x->>'kind' end;
        required_reason:=case when required_route='tournament' then 'bracket' when required_route='rest' then 'insufficient-stamina'
          when not calendar then 'not-tournament-slot' when x->'snapshot'->'starting'->'tournamentOptIn'='false'::jsonb then 'opted-out'
          else 'too-few-entrants' end;
        if r->>'route' is distinct from required_route or r->>'reason' is distinct from required_reason then return false; end if;
      elsif (x->>'kind'='rest') is distinct from (r->>'route'='rest') then return false; end if;
      -- Rest is exactly step 6's fallback at no cost; a bracket costs the frozen tournament price, regular Arena the Arena price.
      if not coalesce((r->>'route'='rest' and r->'reason'='"insufficient-stamina"'::jsonb and r->'staminaDebit'='0'::jsonb)
          or (r->>'route'='tournament' and r->'reason'='"bracket"'::jsonb and r->'staminaDebit'=x->'costs'->'tournament')
          or (r->>'route'='arena' and r->>'reason' in ('not-tournament-slot','opted-out','insufficient-stamina','too-few-entrants')
            and r->'staminaDebit'=x->'costs'->'arena'),false) then return false; end if;
      routed:=routed||jsonb_build_object(gid,true);
      if r->>'route'='tournament' then
        bracketed:=bracketed||jsonb_build_object(gid,jsonb_build_object('activityId',x->'activityId','rating',x->'rating','fighter',x->'fighter'));
        expected:=expected-gid;
      end if;
    end loop;
    if (select count(*) from jsonb_object_keys(routed))<>(select count(*) from jsonb_object_keys(frozen)) then return false; end if;
    bracket:=result->'tournament'->'bracket';
    if not private.valid_bracket(j.id,bracket,bracketed) then return false; end if;
  end if;
  for e in select value from jsonb_array_elements(result->'assignments') loop
    if jsonb_typeof(e) is distinct from 'object' or e->'kind' is null or e->'kind' not in ('"human"'::jsonb,'"npc"'::jsonb)
      or jsonb_typeof(e->'sides') is distinct from 'array' then return false; end if;
    human:=e->>'kind'='human';
    -- PL/pgSQL ends an IF condition at its first THEN, so the kind-dependent shape is computed first.
    keys:=case when human then array['battleId','kind','league','seasonId','sides','slotIndex']
      else array['battleId','kind','league','opponent','seasonId','sides','slotIndex'] end;
    sides:=case when human then 2 else 1 end;
    if (select array_agg(k order by k collate "C") from jsonb_object_keys(e) k) is distinct from keys
      or e->'slotIndex' is distinct from to_jsonb(j.slot_index) or e->'league' is distinct from to_jsonb(league_id)
      or e->'seasonId' is distinct from to_jsonb(season::text) or jsonb_array_length(e->'sides')<>sides then return false; end if;
    for s in select value from jsonb_array_elements(e->'sides') loop
      if jsonb_typeof(s) is distinct from 'object' or jsonb_typeof(s->'gladiatorId') is distinct from 'string'
        or (select array_agg(k order by k collate "C") from jsonb_object_keys(s) k) is distinct from array['activityId','fighter','gladiatorId','rating','strength']
        then return false; end if;
      gid:=s->>'gladiatorId';
      x:=expected->gid;
      if x is null or seen ? gid or s->'activityId' is distinct from x->'activityId' or s->'rating' is distinct from x->'rating'
        or s->'strength' is distinct from x->'strength' or s->'fighter' is distinct from x->'fighter' then return false; end if;
      seen:=seen||jsonb_build_object(gid,true);
    end loop;
    if human then
      if e->'battleId' is distinct from to_jsonb('arena:'||j.slot_index||':'||(e->'sides'->0->>'gladiatorId')||':'||(e->'sides'->1->>'gladiatorId')) then
        return false;
      end if;
    else
      gid:=e->'sides'->0->>'gladiatorId';
      if e->'battleId' is distinct from to_jsonb('arena:'||j.slot_index||':'||gid||':npc') or jsonb_typeof(e->'opponent') is distinct from 'object' then
        return false;
      end if;
      if (select array_agg(k order by k collate "C") from jsonb_object_keys(e->'opponent') k) is distinct from array['id','snapshot']
        or e->'opponent'->'id' is distinct from to_jsonb('npc:'||gid) or e->'opponent'->'snapshot' is distinct from expected->gid->'npc' then
        return false;
      end if;
    end if;
  end loop;
  -- Complete: every regular-Arena entrant appeared, each exactly once (duplicates were refused above).
  if (select count(*) from jsonb_object_keys(seen))<>(select count(*) from jsonb_object_keys(expected)) then return false; end if;
  for e in select value from jsonb_array_elements(result->'assignments') with ordinality as proposed(value,position) order by position loop
    if j.rules_version='v2' and e->>'kind'='npc' then
      gid:=e->'sides'->0->>'gladiatorId';
      human_strength_cents:=(expected->gid->>'strength')::numeric*100;
      -- All prior boundaries have settled before this phase. This slot cannot reveal until all pairing jobs complete.
      select jsonb_build_object('id',d.gladiator_id,'name',s.snapshot->'botArena'->'name','snapshot',s.snapshot->'botArena'->'snapshot') into opponent
      from private.bot_slot_duty d
      join public.activities a on a.slot_index=d.slot_index and a.gladiator_id=d.gladiator_id
      join private.activity_snapshots s on s.activity_id=a.id
      left join private.bot_arena_history h on h.bot_id=d.gladiator_id and h.human_id=gid::uuid and h.last_slot<j.slot_index
      where d.slot_index=j.slot_index and d.directive='arena' and a.status='preparing' and a.resolved_kind='arena'
        and s.rules_version=j.rules_version and s.snapshot->'starting'->>'league'=league_id
        and 4*(s.snapshot->'botArena'->>'strengthCents')::numeric between 3*human_strength_cents and 5*human_strength_cents
        and not exists(select 1 from private.arena_assignments used where used.slot_index=j.slot_index and used.kind='bot'
          and (used.assignment->'opponent'->>'id')::uuid=d.gladiator_id)
      order by h.last_slot nulls first,d.gladiator_id limit 1;
      if found then
        e:=e||jsonb_build_object('kind','bot','opponent',opponent,'battleId','arena:'||j.slot_index||':'||gid||':bot:'||(opponent->>'id'));
      end if;
    end if;
    insert into private.arena_assignments(battle_id,pairing_job_id,slot_index,league,season_index,kind,seed,assignment,created_at_ms)
      values(e->>'battleId',j.id,j.slot_index,league_id,season,e->>'kind',
        encode(extensions.digest(j.seed||':'||(e->>'battleId'),'sha256'),'hex'),e,now_ms);
    insert into private.arena_assignment_sides(activity_id,battle_id,side)
      select (side.value->>'activityId')::uuid,e->>'battleId',(side.ordinality-1)::smallint
      from jsonb_array_elements(e->'sides') with ordinality side(value,ordinality);
  end loop;
  if jsonb_typeof(bracket)='object' then
    tid:=bracket->>'id';
    insert into private.tournaments(id,pairing_job_id,slot_index,league,season_index,rules_version,starts_at_ms,settles_at_ms,size,rounds,reveal_at_ms,created_at_ms)
      values(tid,j.id,j.slot_index,league_id,season,j.rules_version,(bracket->>'startsAtMs')::bigint,(bracket->>'settlesAtMs')::bigint,
        (bracket->>'size')::integer,(bracket->>'rounds')::integer,bracket->'revealAtMs',now_ms);
    -- The display name is frozen with the entry: every bout log of the tournament carries the same names (decision 7).
    insert into private.tournament_entries(tournament_id,gladiator_id,activity_id,rank,rating,fighter,name)
      select tid,(t.value->>'gladiatorId')::uuid,(t.value->>'activityId')::uuid,(t.value->>'rank')::integer,(t.value->>'rating')::bigint,t.value->'fighter',g.name
      from jsonb_array_elements(bracket->'entries') t join public.gladiators g on g.id=(t.value->>'gladiatorId')::uuid;
    insert into private.tournament_bouts(id,tournament_id,round,position,parent_bout_ids,placed,bye,reveal_at_ms,seed,result)
      select o.value->>'id',tid,(o.value->>'round')::integer,(o.value->>'position')::integer,o.value->'parentBoutIds',nullif(o.value->'placed','null'::jsonb),
        (o.value->>'bye')::boolean,(o.value->>'revealAtMs')::bigint,
        case when (o.value->>'bye')::boolean then null else encode(extensions.digest(j.seed||':'||(o.value->>'id'),'sha256'),'hex') end,
        nullif(o.value->'result','null'::jsonb)
      from jsonb_array_elements(bracket->'bouts') o;
  end if;
  return true;
end $function$;

CREATE OR REPLACE FUNCTION private.boundary_pair (
  target bigint
)
  RETURNS text
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare b private.boundaries%rowtype; season bigint; l text; now_ms bigint:=private.planning_now_ms(); seed text; input jsonb; dungeon text; has_arena boolean;
  required_level integer; humans integer; pool jsonb; chosen uuid[]; used uuid[]:='{}'::uuid[];
begin
  select * into b from private.boundaries where slot_index=target;
  select exists(select 1 from public.activities a join private.activity_snapshots s on s.activity_id=a.id
    where a.slot_index=target and a.status='preparing' and not (s.snapshot ? 'botDirective')
    and (a.resolved_kind='arena' or (b.rules_version='v2' and a.requested->>'kind'='arena' and a.resolved_kind='rest'))) into has_arena;
  if not has_arena and not exists(select 1 from public.activities a where a.slot_index=target and a.status='preparing'
    and a.resolved_kind='dungeon') then return null; end if;
  if has_arena then
    season:=private.season_index(target);
    if season is null then return 'epoch'; end if;
    for l in select distinct s.snapshot->'starting'->>'league' from public.activities a join private.activity_snapshots s on s.activity_id=a.id
      where a.slot_index=target and a.status='preparing' and not (s.snapshot ? 'botDirective')
        and (a.resolved_kind='arena' or (b.rules_version='v2' and a.requested->>'kind'='arena' and a.resolved_kind='rest'))
        and not exists(select 1 from private.jobs j where j.dedupe_key='pair:'||target||':'||(s.snapshot->'starting'->>'league')) loop
      seed:=encode(extensions.gen_random_bytes(32),'hex');
      input:=jsonb_set(private.pairing_input(target,l,season,b.rules_version),'{tournament,bracketSeed}',
        to_jsonb(encode(extensions.digest(seed||':bracket','sha256'),'hex')));
      insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
        values('pair','pair:'||target||':'||l,target,null,null,input,seed,b.rules_version,now_ms)
        on conflict (dedupe_key) do nothing;
    end loop;
  end if;
  if b.rules_version='v2' and not exists(select 1 from private.jobs j where j.slot_index=target and j.kind='pair'
    and j.input->>'kind'='dungeon-grouping') then
    -- The coordinator commits all grouping jobs together. Resume the same batch, even after one pool has been accepted.
    -- Hardest first gives the only level-12 bot to Troll Hall when eligible. Each dungeon uses the global vacancy cap.
    for dungeon,required_level in select d.id,d.required_level from (values
      (1,'troll-hall',12),(2,'raider-stronghold',7),(3,'wolf-den',3)) d(priority,id,required_level) order by d.priority loop
      input:=private.grouping_input(target,dungeon,b.rules_version);
      humans:=jsonb_array_length(input->'entrants');
      continue when humans=0;
      select coalesce(jsonb_agg(candidate.entry order by candidate.id),'[]'::jsonb),coalesce(array_agg(candidate.id),'{}') into pool,chosen
      from (
        select a.gladiator_id as id,jsonb_build_object('gladiatorId',a.gladiator_id,'activityId',a.id,'name',g.name,
          'level',s.snapshot->'starting'->'level','role',d.role) as entry
        from private.bot_slot_duty d join public.activities a on a.slot_index=d.slot_index and a.gladiator_id=d.gladiator_id
        join private.activity_snapshots s on s.activity_id=a.id join public.gladiators g on g.id=a.gladiator_id
        where d.slot_index=target and d.directive='on-call' and a.status='preparing' and s.rules_version=b.rules_version
          and a.gladiator_id<>all(used) and (s.snapshot->'starting'->>'level')::int>=required_level
          and (s.snapshot->'starting'->'stamina'->>'current')::bigint>=(s.snapshot->'costs'->>'dungeon')::numeric
        order by a.gladiator_id limit (3*((humans+2)/3)-humans)
      ) candidate;
      used:=used||chosen;
      if jsonb_array_length(pool)>0 then input:=input||jsonb_build_object('bots',pool); end if;
      insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
        values('pair','party:'||target||':'||dungeon,target,null,null,input,encode(extensions.gen_random_bytes(32),'hex'),b.rules_version,now_ms)
        on conflict (dedupe_key) do nothing;
    end loop;
  end if;
  if exists(select 1 from private.jobs j where j.kind='pair' and j.slot_index=target and j.status='operator') then return 'operator'; end if;
  if exists(select 1 from private.jobs j where j.kind='pair' and j.slot_index=target and j.status<>'completed') then return 'pairing'; end if;
  if has_arena then
    -- Only entries written by accepted complete pairing jobs may promote a preliminary Rest.
    update public.activities a set resolved_kind='tournament',
      stamina_debit=case when t.rules_version='v2' then 0 else (s.snapshot->'costs'->>'tournament')::bigint end,
      fallback=case when t.rules_version='v2' then false else a.fallback end
      from private.tournament_entries e join private.tournaments t on t.id=e.tournament_id join private.activity_snapshots s on s.activity_id=e.activity_id
      where t.slot_index=target and a.id=e.activity_id and a.status='preparing'
        and (a.resolved_kind='arena' or (t.rules_version='v2' and s.rules_version='v2' and a.resolved_kind='rest'));
    if exists(select 1 from public.activities a where a.slot_index=target and a.status='preparing' and a.resolved_kind='arena'
      and not exists(select 1 from private.activity_snapshots s where s.activity_id=a.id and s.snapshot->>'botDirective'='arena')
      and not exists(select 1 from private.arena_assignment_sides x where x.activity_id=a.id)) then
      raise exception 'unpaired arena entrant';
    end if;
    if exists(select 1 from public.activities a where a.slot_index=target and a.status='preparing' and a.resolved_kind='tournament'
      and not exists(select 1 from private.tournament_entries e where e.activity_id=a.id)) then
      raise exception 'unbracketed tournament entrant';
    end if;
  end if;
  if exists(select 1 from public.activities a where a.slot_index=target and a.status='preparing' and a.resolved_kind='dungeon'
    and not exists(select 1 from private.bot_slot_duty d where d.slot_index=target and d.gladiator_id=a.gladiator_id and d.directive='on-call')
    and not exists(select 1 from private.dungeon_run_members m where m.activity_id=a.id)) then
    raise exception 'ungrouped dungeon entrant';
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION private.accept_grouping (
  job    uuid,
  result jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare j private.jobs%rowtype; dungeon text; expected jsonb; scoped jsonb; entrant jsonb; pool jsonb; next_bot integer:=0;
  run jsonb; seat jsonb; run_number bigint; seat_number bigint; gid text;
  seen text[]:='{}'::text[]; has_human boolean; has_filler boolean; now_ms bigint;
begin
  select * into j from private.jobs where id=job;
  if not found or j.kind is distinct from 'pair' or j.rules_version is distinct from 'v2'
    or j.gladiator_id is not null or j.activity_id is not null or j.slot_index%3<>1
    or j.input->>'kind' is distinct from 'dungeon-grouping' or j.input->'slotIndex' is distinct from to_jsonb(j.slot_index)
    or j.input->>'rulesVersion' is distinct from j.rules_version
    or jsonb_typeof(j.input->'entrants') is distinct from 'array'
    or jsonb_typeof(result) is distinct from 'object' or jsonb_typeof(result->'runs') is distinct from 'array' then return false; end if;
  dungeon:=j.input->>'dungeonId';
  pool:=coalesce(j.input->'bots','[]'::jsonb);
  if jsonb_typeof(pool) is distinct from 'array' then return false; end if;
  if dungeon is null or dungeon not in ('wolf-den','raider-stronghold','troll-hall')
    or j.dedupe_key is distinct from 'party:'||j.slot_index||':'||dungeon
    or result-'runs'<>'{}'::jsonb or jsonb_array_length(result->'runs') not between 1 and jsonb_array_length(j.input->'entrants')
    then return false; end if;

  -- The job froze names. Compare its identities/builds/levels to the preparing activity snapshots, never the live build or name.
  select coalesce(jsonb_object_agg(value->>'gladiatorId',value),'{}'::jsonb) into expected
    from jsonb_array_elements(j.input->'entrants') where jsonb_typeof(value->'gladiatorId')='string'
      and jsonb_typeof(value->'name')='string';
  if (select count(*) from jsonb_object_keys(expected))<>jsonb_array_length(j.input->'entrants') then return false; end if;
  select coalesce(jsonb_object_agg(a.gladiator_id::text,jsonb_build_object('activityId',a.id,
    'level',s.snapshot->'starting'->'level','build',s.snapshot->'build')),'{}'::jsonb) into scoped
    from public.activities a join private.activity_snapshots s on s.activity_id=a.id
    where a.slot_index=j.slot_index and a.status='preparing' and a.resolved_kind='dungeon'
      and a.requested->>'kind'='dungeon' and a.requested->>'dungeonId'=dungeon and s.rules_version=j.rules_version;

  -- Validate the whole proposal before the first insert, including a bad seat in a later run.
  for run,run_number in select value,ordinality from jsonb_array_elements(result->'runs') with ordinality loop
    if jsonb_typeof(run) is distinct from 'object' or jsonb_typeof(run->'seats') is distinct from 'array' then return false; end if;
    if run-array['runId','seats']<>'{}'::jsonb or jsonb_array_length(run->'seats')<>3
      or run->'runId' is distinct from to_jsonb('dungeon:'||j.slot_index||':'||dungeon||':'||run_number) then return false; end if;
    has_human:=false;
    has_filler:=false;
    for seat,seat_number in select value,ordinality from jsonb_array_elements(run->'seats') with ordinality loop
      if jsonb_typeof(seat) is distinct from 'object' or seat->'seat' is distinct from to_jsonb(seat_number-1) then return false; end if;
      if seat->>'kind'='human' then
        if has_filler or jsonb_typeof(seat->'gladiatorId') is distinct from 'string' then return false; end if;
        gid:=seat->>'gladiatorId';
        entrant:=expected->gid;
        if entrant is null or gid=any(seen) or seat-array['kind','seat'] is distinct from entrant
          or entrant-array['gladiatorId','name'] is distinct from scoped->gid then return false; end if;
        seen:=array_append(seen,gid);
        has_human:=true;
      elsif seat->>'kind'='bot' then
        gid:=seat->>'gladiatorId';
        if not has_human or gid=any(seen) or pool->next_bot is null or seat-array['kind','seat'] is distinct from pool->next_bot
          or not exists(select 1 from public.activities a join private.activity_snapshots s on s.activity_id=a.id
            where a.id::text=seat->>'activityId' and a.gladiator_id::text=gid and a.slot_index=j.slot_index and a.status='preparing'
              and a.resolved_kind in ('rest','training') and s.snapshot->>'botDirective'='on-call' and s.rules_version=j.rules_version)
          then return false; end if;
        seen:=array_append(seen,gid);
        next_bot:=next_bot+1;
        has_filler:=true;
      elsif seat->>'kind'='hireling' then
        if not has_human or next_bot<jsonb_array_length(pool) or seat-array['kind','seat','role']<>'{}'::jsonb or seat->>'role' is null
          or seat->>'role' not in ('guard','striker','skirmisher') then return false; end if;
        has_filler:=true;
      else return false;
      end if;
    end loop;
    if not has_human then return false; end if;
  end loop;
  if next_bot<>jsonb_array_length(pool) or cardinality(seen)-next_bot<>jsonb_array_length(j.input->'entrants') then return false; end if;

  now_ms:=private.planning_now_ms();
  for run in select value from jsonb_array_elements(result->'runs') loop
    insert into private.dungeon_runs(run_id,grouping_job_id,slot_index,dungeon_id,seed,assignment,created_at_ms)
      values(run->>'runId',j.id,j.slot_index,dungeon,encode(extensions.digest(j.seed||':'||(run->>'runId'),'sha256'),'hex'),run,now_ms);
    insert into private.dungeon_run_members(activity_id,run_id,seat)
      select (value->>'activityId')::uuid,run->>'runId',(ordinality-1)::smallint
      from jsonb_array_elements(run->'seats') with ordinality where value->>'kind'='human';
  end loop;
  -- The accepted pool is immutable. Replace the preliminary Training/Rest price, retaining the original request and snapshot.
  update public.activities a set resolved_kind='dungeon',stamina_debit=(s.snapshot->'costs'->>'dungeon')::numeric::bigint,fallback=false
    from jsonb_array_elements(pool) bot join private.activity_snapshots s on s.activity_id=(bot->>'activityId')::uuid
    where a.id=s.activity_id;
  return true;
end $function$;

-- 3. Run jobs and shared reveals. The plan is frozen; each due reveal publishes only a single stage and its fight.
create table if not exists private.dungeon_results (
  run_id text primary key references private.dungeon_runs(run_id),
  simulation_job_id uuid not null references private.jobs(id),
  plan jsonb not null check (jsonb_typeof(plan)='object'),
  created_at_ms bigint not null
);
create index if not exists dungeon_results_simulation_job_idx on private.dungeon_results(simulation_job_id);

create table if not exists public.dungeon_fights (
  run_id text not null references private.dungeon_runs(run_id),
  ordinal smallint not null check (ordinal between 1 and 4),
  reveal_at_ms bigint not null,
  log jsonb not null check (jsonb_typeof(log)='object'),
  primary key(run_id,ordinal)
);
create index if not exists dungeon_fights_reveal_idx on public.dungeon_fights(reveal_at_ms);

alter table private.dungeon_results enable row level security;
alter table public.dungeon_fights enable row level security;
revoke all on private.dungeon_results,public.dungeon_fights from public,anon,authenticated,service_role;
grant select,insert,delete on private.dungeon_results,public.dungeon_fights to service_role;
grant select on public.dungeon_fights to anon,authenticated;
drop policy if exists backend_only on private.dungeon_results;
create policy backend_only on private.dungeon_results to service_role using(true) with check(true);
drop trigger if exists guard_frozen on private.dungeon_results;
create trigger guard_frozen before update on private.dungeon_results for each row execute function private.guard_frozen();
drop policy if exists due_read on public.dungeon_fights;
create policy due_read on public.dungeon_fights for select to anon,authenticated
  using(reveal_at_ms<=floor(extract(epoch from clock_timestamp())*1000)::bigint);


CREATE OR REPLACE FUNCTION private.activity_executor_ready (
  kind text
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select coalesce(kind in ('training','rest','expedition','arena','tournament','dungeon'),false)
$function$;

CREATE OR REPLACE FUNCTION private.prepare_activity_jobs (
  activity uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare a public.activities%rowtype; s private.activity_snapshots%rowtype; simulation uuid; terminal uuid; reveal uuid;
  seat private.arena_assignment_sides%rowtype; x private.arena_assignments%rowtype; entry private.tournament_entries%rowtype;
  t private.tournaments%rowtype; bout private.tournament_bouts%rowtype; first_reveal integer;
  run private.dungeon_runs%rowtype; anchor record;
begin
  select * into a from public.activities where id=activity;
  select * into s from private.activity_snapshots where activity_id=activity;
  if a.resolved_kind not in ('training','rest','expedition','arena','tournament','dungeon') then raise exception 'unsupported activity executor'; end if;
  insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
    values('settlement','settlement:'||a.id,a.slot_index,a.gladiator_id,a.id,
      jsonb_build_object('activityId',a.id,'gladiatorId',a.gladiator_id,'slotIndex',a.slot_index,'resolvedKind',a.resolved_kind,'endsAtMs',a.ends_at_ms),
      s.seed,s.rules_version,a.ends_at_ms) on conflict(dedupe_key) do nothing;
  select id into terminal from private.jobs where dedupe_key='settlement:'||a.id;
  if a.resolved_kind='expedition' then
    insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
      values('simulation','expedition:'||a.id,a.slot_index,a.gladiator_id,a.id,s.snapshot,s.seed,s.rules_version,a.starts_at_ms)
      on conflict(dedupe_key) do nothing;
    select id into simulation from private.jobs where dedupe_key='expedition:'||a.id;
    insert into private.job_dependencies values(terminal,simulation) on conflict do nothing;
  elsif a.resolved_kind='dungeon' then
    if s.snapshot->>'botDirective'='on-call' then
      select r.* into run from private.dungeon_runs r where r.slot_index=a.slot_index
        and r.assignment->'seats' @> jsonb_build_array(jsonb_build_object('kind','bot','activityId',a.id));
    else
      select r.* into run from private.dungeon_run_members m join private.dungeon_runs r using(run_id)
        where m.activity_id=a.id and r.slot_index=a.slot_index;
    end if;
    if not found then raise exception 'ungrouped dungeon entrant'; end if;
    select anchor_activity.id,anchor_activity.gladiator_id,anchor_activity.starts_at_ms,f.rules_version into anchor
      from private.dungeon_run_members m join public.activities anchor_activity on anchor_activity.id=m.activity_id
      join private.activity_snapshots f on f.activity_id=anchor_activity.id
      where m.run_id=run.run_id and m.seat=0 and anchor_activity.slot_index=run.slot_index and anchor_activity.resolved_kind='dungeon';
    if not found then raise exception 'missing dungeon run anchor'; end if;
    -- Any member may be visited first. Phase 8 already holds every member's account lock before this shared FK insert.
    insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
      values('simulation','dungeon:'||run.run_id,run.slot_index,anchor.gladiator_id,anchor.id,
        jsonb_build_object('kind','dungeon','runId',run.run_id,'slotIndex',run.slot_index,'rulesVersion',anchor.rules_version,
          'dungeonId',run.dungeon_id,'startsAtMs',anchor.starts_at_ms,'seats',run.assignment->'seats'),
        run.seed,anchor.rules_version,anchor.starts_at_ms) on conflict(dedupe_key) do nothing;
    select id into simulation from private.jobs where dedupe_key='dungeon:'||run.run_id;
    insert into private.job_dependencies values(terminal,simulation) on conflict do nothing;
  elsif a.resolved_kind='arena' then
    -- Bot Arena attendance has only its private terminal. Any opponent and reveal belong to the human's bout.
    if s.snapshot->>'botDirective'='arena' then return; end if;
    select * into seat from private.arena_assignment_sides where activity_id=a.id;
    if not found then raise exception 'unpaired arena entrant'; end if;
    select * into x from private.arena_assignments where battle_id=seat.battle_id;
    insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
      values('simulation','arena:'||x.battle_id,x.slot_index,(x.assignment->'sides'->0->>'gladiatorId')::uuid,
        (x.assignment->'sides'->0->>'activityId')::uuid,
        jsonb_build_object('kind','arena','battleId',x.battle_id,'slotIndex',x.slot_index,'rulesVersion',s.rules_version,
          'startsAtMs',a.starts_at_ms,'revealAtMs',a.starts_at_ms+3600000,'assignment',x.assignment,
          'names',(select jsonb_agg(g.name order by e.ordinality) from jsonb_array_elements(x.assignment->'sides') with ordinality e(value,ordinality)
            join public.gladiators g on g.id=(e.value->>'gladiatorId')::uuid)),
        x.seed,s.rules_version,a.starts_at_ms)
      on conflict(dedupe_key) do nothing;
    select id into simulation from private.jobs where dedupe_key='arena:'||x.battle_id;
    insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
      values('reveal','arena-reveal:'||a.id,a.slot_index,a.gladiator_id,a.id,jsonb_build_object('activityId',a.id,'ordinal',1),
        s.seed,s.rules_version,a.starts_at_ms+3600000) on conflict(dedupe_key) do nothing;
    select id into reveal from private.jobs where dedupe_key='arena-reveal:'||a.id;
    insert into private.job_dependencies values(reveal,simulation),(terminal,simulation),(terminal,reveal) on conflict do nothing;
    insert into public.activity_stages(activity_id,ordinal,reveal_at_ms,stage) values(a.id,0,a.starts_at_ms,jsonb_build_object(
      'id',a.id::text||':0','kind','staging','revealedAtMs',a.starts_at_ms,'startedAtMs',a.starts_at_ms,'endsAtMs',a.starts_at_ms+3600000,
      'label','Warming up')) on conflict(activity_id,ordinal) do nothing;
  elsif a.resolved_kind='tournament' then
    select * into entry from private.tournament_entries where activity_id=a.id;
    if not found then raise exception 'unbracketed tournament entrant'; end if;
    select * into t from private.tournaments where id=entry.tournament_id;
    if entry.rank=1 then
      for bout in select * from private.tournament_bouts where tournament_id=t.id and not bye order by round,position loop
        insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
          values('simulation','tournament-bout:'||bout.id,t.slot_index,a.gladiator_id,a.id,
            jsonb_build_object('kind','tournament-bout','tournamentId',t.id,'boutId',bout.id),bout.seed,t.rules_version,t.starts_at_ms)
          on conflict(dedupe_key) do nothing;
        insert into private.job_dependencies(job_id,prerequisite_id)
          select child.id,parent.id from private.jobs child
          join jsonb_array_elements_text(bout.parent_bout_ids) pid(value) on true
          join private.jobs parent on parent.dedupe_key='tournament-bout:'||pid.value
          where child.dedupe_key='tournament-bout:'||bout.id
          on conflict do nothing;
        -- Exception 4: the bout's one reveal, due at its stored reveal time, after its bout and its fought parents' reveals.
        insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
          values('reveal','tournament-reveal:'||bout.id,t.slot_index,a.gladiator_id,a.id,
            jsonb_build_object('kind','tournament-reveal','tournamentId',t.id,'boutId',bout.id),s.seed,t.rules_version,bout.reveal_at_ms)
          on conflict(dedupe_key) do nothing;
        insert into private.job_dependencies(job_id,prerequisite_id)
          select r.id,p.id from private.jobs r join private.jobs p on p.dedupe_key='tournament-bout:'||bout.id
          where r.dedupe_key='tournament-reveal:'||bout.id
          union all
          select r.id,p.id from private.jobs r
          join jsonb_array_elements_text(bout.parent_bout_ids) pid(value) on true
          join private.jobs p on p.dedupe_key='tournament-reveal:'||pid.value
          where r.dedupe_key='tournament-reveal:'||bout.id
          on conflict do nothing;
      end loop;
    end if;
    -- Exception 5: this entrant's settlement (and, from rank 1, every entrant's settlement created so far) waits for the
    -- final's bout and its reveal.
    insert into private.job_dependencies(job_id,prerequisite_id)
      select st.id,f.id from private.tournament_entries te join private.jobs st on st.dedupe_key='settlement:'||te.activity_id
      join private.jobs f on f.dedupe_key in ('tournament-bout:'||t.id||':'||t.rounds||':0','tournament-reveal:'||t.id||':'||t.rounds||':0')
      where te.tournament_id=t.id and (entry.rank=1 or te.activity_id=a.id)
      on conflict do nothing;
    -- Staging from the start until the reveal of the entrant's first fought bout: round one, or round two after a bye.
    first_reveal:=case when exists(select 1 from private.tournament_bouts o where o.tournament_id=t.id and o.round=1 and o.bye
      and o.result->>'winnerId'=a.gladiator_id::text) then 1 else 0 end;
    insert into public.activity_stages(activity_id,ordinal,reveal_at_ms,stage) values(a.id,0,a.starts_at_ms,jsonb_build_object(
      'id',a.id::text||':0','kind','staging','revealedAtMs',a.starts_at_ms,'startedAtMs',a.starts_at_ms,
      'endsAtMs',(t.reveal_at_ms->>first_reveal)::bigint,'label','Tournament staging')) on conflict(activity_id,ordinal) do nothing;
  end if;
end $function$;

-- Under the v2 120 s cap, 250 ms floor and one sweep every four attacks, the maximum generic 6v6 log is
-- 12 * 480 ordinary events + 6 * 120 * 5 additional sweep events + victory. The separate raw serialized cap
-- also bounds unknown keys and string sizes. It is deliberately larger than the released 3v3 and major logs.
CREATE OR REPLACE FUNCTION private.safe_party_log (
  value jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  participants jsonb:='[]'::jsonb; events jsonb; p jsonb; e jsonb; k text; projected jsonb;
  ids text[]:='{}'::text[]; sides integer[]:='{}'::integer[]; roles text[]:='{}'::text[];
  duration bigint; elapsed bigint; previous_ms bigint:=0; event_count integer; seq integer:=0;
  attacker integer; defender integer; side integer; party_count integer:=0; hp_index integer:=0;
  participant_keys constant text[]:=array['id','gladiatorId','name','classId','stance','maxHealth','initialHealth',
    'armor','weaponDamage','attackIntervalMs','efficiencyBasisPoints','equipmentSilhouettes','side','role','seat'];
  attribute_keys constant text[]:=array['strength','agility','vitality','endurance','precision'];
  attack_keys constant text[]:=array['kind','sequence','elapsedMs','attackerId','defenderId','hit','critical','defend','evade',
    'damage','healthBefore','healthAfter','sweep'];
  victory_keys constant text[]:=array['kind','sequence','elapsedMs','winnerSide','reason'];
begin
  if jsonb_typeof(value) is distinct from 'object'
    or jsonb_typeof(value->'participants') is distinct from 'array'
    or jsonb_typeof(value->'events') is distinct from 'array'
    or jsonb_typeof(value->'finalHp') is distinct from 'array'
    or octet_length(value::text)>4000000 then
    raise exception 'invalid party log' using errcode='22023';
  end if;
  event_count:=jsonb_array_length(value->'events');
  if jsonb_array_length(value->'participants') not between 2 and 12
    or jsonb_array_length(value->'finalHp')<>jsonb_array_length(value->'participants')
    or event_count not between 1 and 9361
    or not private.safe_integer(value->'durationMs')
    or jsonb_typeof(value->'battleId') is distinct from 'string' or value->>'battleId'=''
    or jsonb_typeof(value->'rulesVersion') is distinct from 'string' or value->>'rulesVersion'=''
    or not coalesce(value->'winnerSide' in ('0'::jsonb,'1'::jsonb),false)
    or coalesce(value->>'victoryReason','') not in ('defeat','health-fraction','tie-break')
    or not coalesce(value->'tieBreakReason' in ('null'::jsonb,'"simultaneous-defeat"'::jsonb,'"equal-health-fraction"'::jsonb),false)
    or ((value->>'victoryReason'='tie-break') is distinct from (value->'tieBreakReason'<>'null'::jsonb)) then
    raise exception 'invalid party log' using errcode='22023';
  end if;
  duration:=(value->>'durationMs')::numeric;
  if duration>120000 then raise exception 'invalid party log' using errcode='22023'; end if;

  for p in select * from jsonb_array_elements(value->'participants') loop
    foreach k in array array['id','name','stance','role'] loop
      if jsonb_typeof(p->k) is distinct from 'string' or p->>k='' then
        raise exception 'invalid party log' using errcode='22023';
      end if;
    end loop;
    if p->>'id'=any(ids)
      or p->>'stance' not in ('balanced','offensive','defensive')
      or not coalesce(p->'classId' in ('null'::jsonb,'"berserker"'::jsonb,'"guardian"'::jsonb,'"duelist"'::jsonb),false)
      or coalesce(jsonb_typeof(p->'gladiatorId'),'') not in ('null','string')
      or not coalesce(p->'side' in ('0'::jsonb,'1'::jsonb),false)
      or not coalesce(p->'seat' in ('null'::jsonb,'0'::jsonb,'1'::jsonb,'2'::jsonb),false)
      or (p->'side'='0'::jsonb and p->>'role' not in ('gladiator','bot','hireling'))
      or (p->'side'='1'::jsonb and (p->>'role' not in ('monster','major') or p->'seat'<>'null'::jsonb))
      or (p->>'role'='bot' and (p->'seat'='null'::jsonb or p->>'gladiatorId' is distinct from p->>'id'))
      or jsonb_typeof(p->'attributes') is distinct from 'object'
      or jsonb_typeof(p->'equipmentSilhouettes') is distinct from 'array' then
      raise exception 'invalid party log' using errcode='22023';
    end if;
    foreach k in array array['maxHealth','initialHealth','efficiencyBasisPoints'] loop
      if not private.safe_integer(p->k,1) then raise exception 'invalid party log' using errcode='22023'; end if;
    end loop;
    if not private.safe_integer(p->'attackIntervalMs',250)
      or not private.safe_integer(value->'finalHp'->hp_index) then
      raise exception 'invalid party log' using errcode='22023';
    end if;
    if (p->>'initialHealth')::numeric>(p->>'maxHealth')::numeric
      or (value->'finalHp'->>hp_index)::numeric>(p->>'initialHealth')::numeric then
      raise exception 'invalid party log' using errcode='22023';
    end if;
    foreach k in array array['armor','weaponDamage'] loop
      if jsonb_typeof(p->k) is distinct from 'number' then raise exception 'invalid party log' using errcode='22023'; end if;
    end loop;
    foreach k in array attribute_keys loop
      if jsonb_typeof(p->'attributes'->k) is distinct from 'number' then raise exception 'invalid party log' using errcode='22023'; end if;
    end loop;
    if exists(select 1 from jsonb_array_elements(p->'equipmentSilhouettes') s where jsonb_typeof(s)<>'string') then
      raise exception 'invalid party log' using errcode='22023';
    end if;
    side:=(p->>'side')::numeric;
    if side=0 then party_count:=party_count+1; end if;
    ids:=array_append(ids,p->>'id'); sides:=array_append(sides,side); roles:=array_append(roles,p->>'role');
    hp_index:=hp_index+1;
    projected:=private.json_project(p,participant_keys)||jsonb_build_object('attributes',private.json_project(p->'attributes',attribute_keys));
    participants:=participants||jsonb_build_array(projected);
  end loop;
  if party_count not between 1 and 6 or cardinality(ids)-party_count not between 1 and 6 then
    raise exception 'invalid party log' using errcode='22023';
  end if;

  for e in select * from jsonb_array_elements(value->'events') loop
    if e->'sequence' is distinct from to_jsonb(seq) or not private.safe_integer(e->'elapsedMs') then
      raise exception 'invalid party log' using errcode='22023';
    end if;
    elapsed:=(e->>'elapsedMs')::numeric;
    if elapsed<previous_ms or elapsed>duration then raise exception 'invalid party log' using errcode='22023'; end if;
    if seq=event_count-1 then
      if e->>'kind' is distinct from 'victory' or e->'winnerSide' is distinct from value->'winnerSide'
        or e->'reason' is distinct from value->'victoryReason' or elapsed<>duration then
        raise exception 'invalid party log' using errcode='22023';
      end if;
    else
      if e->>'kind' is distinct from 'attack'
        or jsonb_typeof(e->'attackerId') is distinct from 'string'
        or jsonb_typeof(e->'defenderId') is distinct from 'string' then
        raise exception 'invalid party log' using errcode='22023';
      end if;
      attacker:=array_position(ids,e->>'attackerId'); defender:=array_position(ids,e->>'defenderId');
      if attacker is null or defender is null or sides[attacker]=sides[defender]
        or (e->'sweep'='true'::jsonb and roles[attacker]<>'major') then
        raise exception 'invalid party log' using errcode='22023';
      end if;
      foreach k in array array['hit','critical','defend','evade','sweep'] loop
        if jsonb_typeof(e->k) is distinct from 'boolean' then raise exception 'invalid party log' using errcode='22023'; end if;
      end loop;
      foreach k in array array['damage','healthBefore','healthAfter'] loop
        if not private.safe_integer(e->k) then raise exception 'invalid party log' using errcode='22023'; end if;
      end loop;
    end if;
    previous_ms:=elapsed; seq:=seq+1;
  end loop;
  -- Aggregate in log order without copying a growing JSONB array for every event.
  select jsonb_agg(private.json_project(entry.val,case when entry.n=event_count then victory_keys else attack_keys end) order by entry.n)
    into events from jsonb_array_elements(value->'events') with ordinality entry(val,n);
  return private.json_project(value,array['battleId','rulesVersion','durationMs','winnerSide','victoryReason','finalHp','tieBreakReason'])
    ||jsonb_build_object('participants',participants,'events',events);
end $function$;

CREATE OR REPLACE FUNCTION private.accept_dungeon_result (
  job    uuid,
  result jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  j private.jobs%rowtype; run private.dungeon_runs%rowtype; anchor record; frozen_plan jsonb;
  f jsonb; stage jsonb; outcome jsonb; reward jsonb; loot jsonb; log jsonb; ref jsonb;
  next_stage integer:=0; fight_count integer; stage_count integer; fight_ordinal integer:=0; member_count integer;
  stage_ms bigint; start_ms bigint; end_ms bigint; previous_end bigint;
  members_seen text[]:='{}'::text[]; terminals uuid[]; bot_terminals uuid[]; entered jsonb; wins jsonb; prior_job uuid; reveal_job uuid;
  bot_seats jsonb;
begin
  select * into j from private.jobs where id=job;
  if not found then return false; end if;
  select * into run from private.dungeon_runs r where r.run_id=j.input->>'runId' and r.slot_index=j.slot_index;
  if not found then return false; end if;
  select a.id,a.gladiator_id,a.starts_at_ms,a.ends_at_ms,s.rules_version,s.seed into anchor
    from private.dungeon_run_members m join public.activities a on a.id=m.activity_id
    join private.activity_snapshots s on s.activity_id=a.id
    where m.run_id=run.run_id and m.seat=0 and a.slot_index=run.slot_index and a.resolved_kind='dungeon';
  if not found or j.activity_id is distinct from anchor.id or j.gladiator_id is distinct from anchor.gladiator_id
    or j.rules_version is distinct from anchor.rules_version then return false; end if;

  if j.kind='simulation' and j.input->>'kind'='dungeon' then
    if j.dedupe_key<>'dungeon:'||run.run_id or j.seed<>run.seed or j.due_at_ms<>anchor.starts_at_ms
      or j.input is distinct from jsonb_build_object('kind','dungeon','runId',run.run_id,'slotIndex',run.slot_index,
        'rulesVersion',anchor.rules_version,'dungeonId',run.dungeon_id,'startsAtMs',anchor.starts_at_ms,'seats',run.assignment->'seats')
      or jsonb_typeof(result) is distinct from 'object' or result->'runId' is distinct from to_jsonb(run.run_id)
      or result->'rulesVersion' is distinct from to_jsonb(anchor.rules_version)
      or result->'dungeonId' is distinct from to_jsonb(run.dungeon_id) or result->>'catalogVersion' is distinct from 'v1'
      or jsonb_typeof(result->'fights') is distinct from 'array' or jsonb_typeof(result->'stages') is distinct from 'array'
      or jsonb_typeof(result->'outcomes') is distinct from 'array' then return false; end if;
    fight_count:=jsonb_array_length(result->'fights'); stage_count:=jsonb_array_length(result->'stages');
    if fight_count not between 1 and 4 or stage_count not between 4 and 10 then return false; end if;
    select coalesce(jsonb_agg(s),'[]'::jsonb) into bot_seats from jsonb_array_elements(run.assignment->'seats') s where s->>'kind'='bot';
    for f in select * from jsonb_array_elements(result->'fights') loop
      fight_ordinal:=fight_ordinal+1;
      if f->'ordinal' is distinct from to_jsonb(fight_ordinal)
        or f->>'kind' is distinct from (case when fight_ordinal=4 then 'major' else 'room' end)
        or f->'offsetMs' is distinct from to_jsonb(fight_ordinal*960000)
        or jsonb_typeof(f->'won') is distinct from 'boolean' then return false; end if;
      begin
        log:=private.safe_party_log(f->'log');
      exception when invalid_parameter_value then return false;
      end;
      if log->>'battleId'<>run.run_id||':fight:'||fight_ordinal or log->>'rulesVersion'<>anchor.rules_version
        or f->'won' is distinct from to_jsonb(log->'winnerSide'='0'::jsonb) then return false; end if;
      -- A bot starts the first fight and can fall thereafter. Its frozen identity cannot be presented as another role or seat.
      if exists(select 1 from jsonb_array_elements(log->'participants') p
        where p->>'role'='bot' and not exists(select 1 from jsonb_array_elements(bot_seats) s
          where p->'seat'=s->'seat' and p->'gladiatorId'=s->'gladiatorId' and p->'name'=s->'name'))
        or exists(select 1 from jsonb_array_elements(bot_seats) s where
          exists(select 1 from jsonb_array_elements(log->'participants') p where p->>'role'<>'bot'
            and ((p->'side'='0'::jsonb and p->'seat'=s->'seat') or p->'id'=s->'gladiatorId' or p->'gladiatorId'=s->'gladiatorId'))
          or (fight_ordinal=1 and not exists(select 1 from jsonb_array_elements(log->'participants') p
            where p->>'role'='bot' and p->'seat'=s->'seat'))) then return false; end if;
    end loop;

    fight_ordinal:=0; previous_end:=anchor.starts_at_ms;
    for stage in select * from jsonb_array_elements(result->'stages') loop
      if stage->>'id' is distinct from run.run_id||':'||next_stage
        or coalesce(stage->>'kind','') not in ('depart','room','major','exploration','travel','return')
        or jsonb_typeof(stage->'label') is distinct from 'string' or stage->>'label'=''
        or not private.safe_integer(stage->'revealedAtMs') or not private.safe_integer(stage->'startedAtMs')
        or not private.safe_integer(stage->'endsAtMs') then return false; end if;
      stage_ms:=(stage->>'revealedAtMs')::numeric; start_ms:=(stage->>'startedAtMs')::numeric; end_ms:=(stage->>'endsAtMs')::numeric;
      if stage_ms<previous_end or stage_ms>start_ms or start_ms>end_ms or end_ms>anchor.ends_at_ms then return false; end if;
      if next_stage=0 then
        if stage->>'kind'<>'depart' or stage_ms<>anchor.starts_at_ms or start_ms<>anchor.starts_at_ms then return false; end if;
      elsif next_stage=stage_count-1 then
        if stage->>'kind'<>'return' or stage_ms<>anchor.ends_at_ms or start_ms<>anchor.ends_at_ms then return false; end if;
      elsif stage->>'kind'='depart' then return false;
      end if;
      if stage->>'kind' in ('room','major') then
        f:=result->'fights'->fight_ordinal;
        fight_ordinal:=fight_ordinal+1;
        ref:=stage->'fight';
        if f is null or stage->'kind' is distinct from f->'kind'
          or ref->'runId' is distinct from to_jsonb(run.run_id) or ref->'ordinal' is distinct from to_jsonb(fight_ordinal)
          or stage_ms<>anchor.starts_at_ms+fight_ordinal*960000 or start_ms<>stage_ms
          or end_ms<>start_ms+(f->'log'->>'durationMs')::numeric then return false; end if;
      elsif stage ? 'fight' then return false;
      end if;
      previous_end:=end_ms; next_stage:=next_stage+1;
    end loop;
    if fight_ordinal<>fight_count then return false; end if;

    select count(*)::integer,array_agg(st.id order by m.seat) into member_count,terminals
      from private.dungeon_run_members m join public.activities a on a.id=m.activity_id
      left join private.jobs st on st.dedupe_key='settlement:'||a.id and st.kind='settlement'
        and st.activity_id=a.id and st.gladiator_id=a.gladiator_id and st.slot_index=run.slot_index
      where m.run_id=run.run_id and a.slot_index=run.slot_index and a.resolved_kind='dungeon';
    if member_count not between 1 and 3 or jsonb_array_length(result->'outcomes')<>member_count
      or array_position(terminals,null) is not null then return false; end if;
    -- Bots have internal terminals, but the member outcomes and reward checks below remain human-only.
    select coalesce(array_agg(st.id),'{}') into bot_terminals from jsonb_array_elements(bot_seats) s
      left join private.jobs st on st.dedupe_key='settlement:'||(s->>'activityId') and st.kind='settlement'
        and st.activity_id=(s->>'activityId')::uuid and st.gladiator_id=(s->>'gladiatorId')::uuid
        and st.slot_index=run.slot_index and st.due_at_ms=anchor.ends_at_ms;
    if array_position(bot_terminals,null) is not null then return false; end if;
    for outcome in select * from jsonb_array_elements(result->'outcomes') loop
      reward:=outcome->'rewards';
      if jsonb_typeof(outcome->'activityId') is distinct from 'string' or jsonb_typeof(outcome->'gladiatorId') is distinct from 'string'
        or outcome->>'activityId'=any(members_seen)
        or not exists(select 1 from private.dungeon_run_members m join public.activities a on a.id=m.activity_id
          where m.run_id=run.run_id and m.activity_id::text=outcome->>'activityId' and a.gladiator_id::text=outcome->>'gladiatorId')
        or coalesce(outcome->>'result','') not in ('victory','defeat') or jsonb_typeof(outcome->'success') is distinct from 'boolean'
        or jsonb_typeof(outcome->'overLevel') is distinct from 'boolean'
        or outcome->'success' is distinct from to_jsonb(outcome->>'result'='victory')
        or not private.safe_integer(reward->'xp') or not private.safe_integer(reward->'money')
        or jsonb_typeof(reward->'loot') is distinct from 'array' then return false; end if;
      -- Check ordinals against the accepted fight log identities and winners; the executor still owns all reward amounts.
      select coalesce(jsonb_agg(fight.val->'ordinal' order by fight.n),'[]'::jsonb),
        coalesce(jsonb_agg(fight.val->'ordinal' order by fight.n) filter(where fight.val->'won'='true'::jsonb),'[]'::jsonb)
        into entered,wins from jsonb_array_elements(result->'fights') with ordinality fight(val,n)
        where exists(select 1 from jsonb_array_elements(fight.val->'log'->'participants') p
          where p->>'role'='gladiator' and p->'gladiatorId'=outcome->'gladiatorId');
      if outcome->'entered' is distinct from entered or outcome->'won' is distinct from wins
        or outcome->'success' is distinct from to_jsonb(wins @> '[4]'::jsonb) then return false; end if;
      for loot in select * from jsonb_array_elements(reward->'loot') loop
        if jsonb_typeof(loot->'catalogId') is distinct from 'string' or loot->>'catalogId'=''
          or loot->'catalogVersion' is distinct from result->'catalogVersion'
          or loot->>'origin' is distinct from 'expedition' or not private.safe_integer(loot->'quantity',1) then return false; end if;
      end loop;
      members_seen:=array_append(members_seen,outcome->>'activityId');
    end loop;

    insert into private.dungeon_results(run_id,simulation_job_id,plan,created_at_ms)
      values(run.run_id,j.id,result,private.planning_now_ms()) on conflict(run_id) do nothing;
    if not found then return false; end if;
    prior_job:=j.id; next_stage:=0;
    for stage in select * from jsonb_array_elements(result->'stages') loop
      insert into private.jobs(kind,dedupe_key,slot_index,gladiator_id,activity_id,input,seed,rules_version,due_at_ms)
        values('reveal','dungeon-reveal:'||run.run_id||':'||next_stage,run.slot_index,anchor.gladiator_id,anchor.id,
          jsonb_build_object('kind','dungeon-reveal','runId',run.run_id,'ordinal',next_stage),anchor.seed,j.rules_version,
          (stage->>'revealedAtMs')::numeric::bigint) on conflict(dedupe_key) do nothing;
      select id into reveal_job from private.jobs where dedupe_key='dungeon-reveal:'||run.run_id||':'||next_stage;
      insert into private.job_dependencies values(reveal_job,prior_job) on conflict do nothing;
      prior_job:=reveal_job; next_stage:=next_stage+1;
    end loop;
    insert into private.job_dependencies(job_id,prerequisite_id)
      select id,prior_job from unnest(terminals||bot_terminals) t(id) on conflict do nothing;
    return true;

  elsif j.kind='reveal' and j.input->>'kind'='dungeon-reveal' then
    if j.seed<>anchor.seed or not private.safe_integer(j.input->'ordinal')
      or j.due_at_ms>private.planning_now_ms() or not private.dependencies_ready(j.id) then return false; end if;
    if (j.input->>'ordinal')::numeric>9 then return false; end if;
    next_stage:=(j.input->>'ordinal')::numeric;
    if j.dedupe_key<>'dungeon-reveal:'||run.run_id||':'||next_stage then return false; end if;
    select d.plan into frozen_plan from private.dungeon_results d where d.run_id=run.run_id;
    stage:=frozen_plan->'stages'->next_stage;
    if stage is null or j.due_at_ms<>(stage->>'revealedAtMs')::numeric then return false; end if;
    ref:=stage->'fight';
    stage:=private.json_project(stage,array['kind','label','revealedAtMs','startedAtMs','endsAtMs']);
    if ref is not null then
      fight_ordinal:=(ref->>'ordinal')::numeric;
      f:=frozen_plan->'fights'->(fight_ordinal-1);
      begin
        log:=private.safe_party_log(f->'log');
      exception when invalid_parameter_value then return false;
      end;
      insert into public.dungeon_fights(run_id,ordinal,reveal_at_ms,log)
        values(run.run_id,fight_ordinal,j.due_at_ms,log) on conflict(run_id,ordinal) do nothing;
      stage:=stage||jsonb_build_object('fight',jsonb_build_object('runId',run.run_id,'ordinal',fight_ordinal));
    end if;
    -- Shared reveal: only KEY SHARE on the activity FKs after the reveal job row. Member settlements wait on it.
    insert into public.activity_stages(activity_id,ordinal,reveal_at_ms,stage)
      select m.activity_id,next_stage,j.due_at_ms,stage||jsonb_build_object('id',m.activity_id::text||':'||next_stage)
      from private.dungeon_run_members m where m.run_id=run.run_id order by m.seat
      on conflict(activity_id,ordinal) do nothing;
    return true;
  end if;
  return false;
end $function$;


-- SQL08 simulation and due reveal. Both retained bout routes use the same fields and result path.
CREATE OR REPLACE FUNCTION private.accept_arena_result (
  job    uuid,
  result jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare j private.jobs%rowtype; a public.activities%rowtype; x private.arena_assignments%rowtype; seat private.arena_assignment_sides%rowtype;
  log jsonb; now_ms bigint; human boolean; sides integer; side jsonb; fighter jsonb; p jsonb; o jsonb;
  expected_id text; expected_gid jsonb; won boolean; delta numeric; bot boolean;
begin
  select * into j from private.jobs where id=job for update;
  now_ms:=private.planning_now_ms();
  if not found or j.status is distinct from 'leased' or j.lease_until_ms<=now_ms or j.due_at_ms>now_ms or not private.dependencies_ready(j.id) then
    return false;
  end if;
  select * into a from public.activities where id=j.activity_id;
  if a.resolved_kind is distinct from 'arena' then return false; end if;
  if j.kind='simulation' then
    select * into x from private.arena_assignments where battle_id=j.input->>'battleId';
    if not found or j.dedupe_key is distinct from 'arena:'||x.battle_id or jsonb_typeof(result) is distinct from 'object'
      or (select array_agg(k order by k collate "C") from jsonb_object_keys(result) k) is distinct from array['battleId','log','outcomes']
      or result->>'battleId' is distinct from x.battle_id or jsonb_typeof(result->'outcomes') is distinct from 'array' then
      return false;
    end if;
    begin
      log:=private.safe_battle_log(result->'log');
    exception when others then
      return false;
    end;
    human:=x.kind='human';
    bot:=x.kind='bot';
    if bot and (j.rules_version<>'v2' or j.input->'assignment' is distinct from x.assignment) then return false; end if;
    sides:=case when human then 2 else 1 end;
    if log->>'battleId' is distinct from x.battle_id or log->>'rulesVersion' is distinct from j.rules_version
      or jsonb_array_length(result->'outcomes')<>sides
      or log->>'winnerId' not in (log->'participants'->0->>'id',log->'participants'->1->>'id')
      or (log->'events'->-1)->>'kind' is distinct from 'victory' or (log->'events'->-1)->>'winnerId' is distinct from log->>'winnerId' then
      return false;
    end if;
    -- Humans and bots use frozen public identities. The NPC uses npc:<entrant> with a null gladiatorId.
    for i in 0..1 loop
      p:=log->'participants'->i;
      if i<sides then
        side:=x.assignment->'sides'->i;
        fighter:=side->'fighter';
        expected_id:=side->>'gladiatorId';
        expected_gid:=side->'gladiatorId';
        if p->'name' is distinct from j.input->'names'->i then return false; end if;
      else
        fighter:=x.assignment->'opponent'->'snapshot';
        expected_id:=x.assignment->'opponent'->>'id';
        expected_gid:=case when bot then x.assignment->'opponent'->'id' else 'null'::jsonb end;
        if (bot and p->'name' is distinct from x.assignment->'opponent'->'name')
          or coalesce(p->>'name','')='' then return false; end if;
      end if;
      if p->>'id' is distinct from expected_id or p->'gladiatorId' is distinct from expected_gid
        or p->'classId' is distinct from fighter->'classId' or p->'stance' is distinct from fighter->'stance'
        or p->'attributes' is distinct from fighter->'attributes' or p->'maxHealth' is distinct from fighter->'maxHealth'
        or p->'initialHealth' is distinct from fighter->'maxHealth' or p->'armor' is distinct from fighter->'armor'
        or p->'weaponDamage' is distinct from fighter->'weaponDamage' or p->'attackIntervalMs' is distinct from fighter->'attackIntervalMs'
        or p->'equipmentSilhouettes' is distinct from fighter->'equipmentSilhouettes'
        or (bot and p->'efficiencyBasisPoints' is distinct from to_jsonb(floor((fighter->>'efficiency')::double precision*10000+0.5))) then
        return false;
      end if;
    end loop;
    -- One outcome per side, in assignment order, consistent with the logged winner and the frozen ratings.
    for i in 0..sides-1 loop
      o:=result->'outcomes'->i;
      side:=x.assignment->'sides'->i;
      if jsonb_typeof(o) is distinct from 'object' or jsonb_typeof(o->'rewards') is distinct from 'object'
        or (select array_agg(k order by k collate "C") from jsonb_object_keys(o) k)
          is distinct from array['activityId','gladiatorId','ratingAfter','ratingBefore','ratingDelta','result','rewards','success']
        or (select array_agg(k order by k collate "C") from jsonb_object_keys(o->'rewards') k)
          is distinct from array['attributePoints','items','money','overflowMoney','renown','xp']
        or o->'gladiatorId' is distinct from side->'gladiatorId' or o->'activityId' is distinct from side->'activityId' then
        return false;
      end if;
      won:=log->>'winnerId'=side->>'gladiatorId';
      if o->'result' is distinct from to_jsonb(case when won then 'victory' else 'defeat' end) or o->'success' is distinct from to_jsonb(won)
        or o->'rewards'->'money' is distinct from '0'::jsonb or o->'rewards'->'xp' is distinct from '0'::jsonb
        or o->'rewards'->'attributePoints' is distinct from '0'::jsonb or o->'rewards'->'overflowMoney' is distinct from '0'::jsonb
        or o->'rewards'->'items' is distinct from '[]'::jsonb or not private.safe_integer(o->'rewards'->'renown')
        or o->'ratingBefore' is distinct from side->'rating' or not private.safe_integer(o->'ratingAfter')
        or not private.safe_integer(o->'ratingDelta',-9007199254740991) then
        return false;
      end if;
      -- V2 human-vs-human renown is 10/2. A fifth, floored, is 2/0. The other currencies are checked above.
      if bot and o->'rewards'->'renown' is distinct from to_jsonb((case when won then 10 else 2 end)/5) then return false; end if;
      delta:=(o->>'ratingAfter')::numeric-(o->>'ratingBefore')::numeric;
      if (o->>'ratingDelta')::numeric<>delta or (not human and delta<>0) or (human and won and delta<0) or (human and not won and delta>0) then
        return false;
      end if;
    end loop;
    -- The base sanitizer drops every extra worker field. Only the validated opponent gets the public tag.
    if bot then log:=jsonb_set(log,'{participants,1,botTeam}','"ludus-nimbus"'::jsonb); end if;
    insert into private.arena_results(battle_id,simulation_job_id,log,outcomes,created_at_ms) values(x.battle_id,j.id,log,result->'outcomes',now_ms);
    return true;
  elsif j.kind='reveal' then
    -- The side's bout stage at minute 60: the battle's one frozen log, labelled from this side's perspective (exception 8).
    select * into seat from private.arena_assignment_sides where activity_id=a.id;
    select * into x from private.arena_assignments where battle_id=seat.battle_id;
    bot:=x.kind='bot';
    select r.log into log from private.arena_results r where r.battle_id=seat.battle_id;
    if log is null or (j.input->>'ordinal')::integer is distinct from 1 then return false; end if;
    insert into public.activity_stages(activity_id,ordinal,reveal_at_ms,stage) values(a.id,1,j.due_at_ms,jsonb_build_object(
      'id',a.id::text||':1','kind','bout','revealedAtMs',j.due_at_ms,'startedAtMs',j.due_at_ms,
      'endsAtMs',j.due_at_ms+(log->>'durationMs')::bigint,
      'label',case when log->>'winnerId'=a.gladiator_id::text then 'Bout: victory' else 'Bout: defeat' end,'battleLog',log)
      ||case when bot then jsonb_build_object('arenaMode','unranked') else '{}'::jsonb end);
    if bot then
      insert into private.bot_arena_history as h(human_id,bot_id,last_slot)
        values(a.gladiator_id,(x.assignment->'opponent'->>'id')::uuid,x.slot_index)
        on conflict(human_id,bot_id) do update set last_slot=excluded.last_slot where h.last_slot<excluded.last_slot;
    end if;
    return true;
  end if;
  return false;
end $function$;

CREATE OR REPLACE FUNCTION public.complete_job (
  job_id      uuid,
  lease_token uuid,
  result      jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare j private.jobs%rowtype; now_ms bigint;
begin
  if complete_job.job_id is null or complete_job.lease_token is null then return jsonb_build_object('ok',false,'code','invalid'); end if;
  select * into j from private.jobs where id=complete_job.job_id for update;
  now_ms:=private.planning_now_ms();
  if not found then return jsonb_build_object('ok',false,'code','not-found'); end if;
  if j.status='completed' and j.lease_token=complete_job.lease_token then
    return jsonb_build_object('ok',true,'jobId',j.id,'replayed',true);
  end if;
  if j.status<>'leased' or j.lease_token is distinct from complete_job.lease_token or j.lease_until_ms<=now_ms then
    return jsonb_build_object('ok',false,'code','conflict');
  end if;
  if not private.dependencies_ready(j.id) or j.due_at_ms>now_ms then return jsonb_build_object('ok',false,'code','processing'); end if;
  if j.kind='settlement' then return jsonb_build_object('ok',false,'code','invalid');
  elsif j.kind='prepare' then
    if not private.valid_preparation(j.id,result) then return jsonb_build_object('ok',false,'code','invalid'); end if;
  elsif j.kind='pair' then
    if j.input->>'kind'='dungeon-grouping' then
      if not private.accept_grouping(j.id,result) then return jsonb_build_object('ok',false,'code','invalid'); end if;
    elsif not private.accept_pairing(j.id,result) then return jsonb_build_object('ok',false,'code','invalid');
    end if;
  elsif (j.kind='simulation' and j.input->>'kind'='dungeon')
    or (j.kind='reveal' and j.input->>'kind'='dungeon-reveal') then
    if not private.accept_dungeon_result(j.id,result) then return jsonb_build_object('ok',false,'code','invalid'); end if;
  elsif not private.accept_job_result(j.id,result) then return jsonb_build_object('ok',false,'code','invalid');
  end if;
  update private.jobs set status='completed',result=complete_job.result,completed_at_ms=now_ms where id=j.id;
  update private.job_attempts set finished_at_ms=now_ms,outcome='completed' where job_attempts.job_id=j.id and attempt=j.attempts;
  return jsonb_build_object('ok',true,'jobId',j.id);
end $function$;

revoke all on function private.planning_command(uuid,uuid,jsonb,text),private.valid_preparation(uuid,jsonb),
  private.boundary_check_stamina(bigint),private.grouping_input(bigint,text,text),private.boundary_pair(bigint),
  private.accept_grouping(uuid,jsonb),public.complete_job(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function private.planning_command(uuid,uuid,jsonb,text),private.valid_preparation(uuid,jsonb),
  private.boundary_check_stamina(bigint),private.grouping_input(bigint,text,text),private.boundary_pair(bigint),
  private.accept_grouping(uuid,jsonb),public.complete_job(uuid,uuid,jsonb) to service_role;
revoke all on function private.safe_party_log(jsonb),private.accept_dungeon_result(uuid,jsonb)
  from public,anon,authenticated,service_role;
grant execute on function private.safe_party_log(jsonb),private.accept_dungeon_result(uuid,jsonb) to service_role;
-- 4. Settle one member under its own locks, project its retained outcome, and prune shared replay detail.

-- M20's claim, with one bounded exception for a dungeon's due final reveal and its due member settlements.
-- Lease that complete bundle first at its due time. Keep the single-job and legacy reveal paths in their existing order.
CREATE OR REPLACE FUNCTION public.claim_jobs (
  worker_id   uuid,
  kind        text,
  batch_limit integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare now_ms bigint:=private.planning_now_ms(); cap integer; leases jsonb; picked uuid[]:='{}'::uuid[]; candidate record; waits uuid[];
  held uuid[]; settlement uuid;
begin
  if claim_jobs.worker_id is null or claim_jobs.kind is null or claim_jobs.kind not in ('prepare','pair','simulation','reveal','settlement')
    or batch_limit is null or batch_limit<1 then
    raise exception 'invalid claim' using errcode='22023';
  end if;
  cap:=least(batch_limit,case when claim_jobs.kind='simulation' then 5 else 20 end);
  perform private.sweep_exhausted_leases(now_ms);
  if claim_jobs.kind<>'settlement' then
    select coalesce(array_agg(x.id order by x.due_at_ms,x.id),'{}'::uuid[]) into picked from (
      select j.id,j.due_at_ms from private.jobs j
      where j.kind=claim_jobs.kind and j.due_at_ms<=now_ms
        and private.dependencies_ready(j.id)
        and (j.status='pending' or (j.status='leased' and j.lease_until_ms<=now_ms and j.attempts<j.max_attempts))
      order by j.due_at_ms,j.id limit cap for update skip locked) x;
  else
    for candidate in
      select coalesce(dungeon.id,j.id) as id,dungeon.id is not null as dungeon_bundle,
        bool_or(private.dependencies_ready(j.id)) as ready,min(j.due_at_ms) as due_at_ms,
        array_agg(j.id order by j.id) as member_ids
      from private.jobs j
      left join lateral (
        -- Only the final dungeon reveal is a direct prerequisite of its members' settlements and due with them.
        select p.id from private.job_dependencies d join private.jobs p on p.id=d.prerequisite_id
        where j.input->>'resolvedKind'='dungeon' and d.job_id=j.id and p.kind='reveal'
          and p.input->>'kind'='dungeon-reveal' and p.status<>'completed'
          and p.slot_index=j.slot_index and p.due_at_ms=j.due_at_ms
        order by p.id limit 1
      ) dungeon on true
      where j.kind='settlement' and j.due_at_ms<=now_ms
        and (j.status='pending' or (j.status='leased' and j.lease_until_ms<=now_ms and j.attempts<j.max_attempts))
        and (private.dependencies_ready(j.id) or private.released_by_due_reveals(j.id,now_ms))
      group by 1,2
      order by due_at_ms,dungeon_bundle desc,id
    loop
      exit when cardinality(picked)>=cap;
      if candidate.dungeon_bundle then
        -- Fit the whole party before taking locks. Same-due independent jobs can fill the tail of a batch.
        continue when cardinality(candidate.member_ids) not between 1 and 3
          or cardinality(picked)+cardinality(candidate.member_ids)+1>cap;
        begin
          perform 1 from private.jobs p where p.id=candidate.id and p.kind='reveal'
            and p.input->>'kind'='dungeon-reveal' and p.due_at_ms=candidate.due_at_ms
            and (p.status='pending' or (p.status='leased' and p.lease_until_ms<=now_ms and p.attempts<p.max_attempts))
            and private.dependencies_ready(p.id)
            for update nowait;
          continue when not found;
          select coalesce(array_agg(x.id order by x.id),'{}'::uuid[]) into held from (
            select m.id from private.jobs m join private.job_dependencies d on d.job_id=m.id
            where m.id=any(candidate.member_ids) and d.prerequisite_id=candidate.id
              and m.kind='settlement' and m.input->>'resolvedKind'='dungeon' and m.due_at_ms=candidate.due_at_ms
              and (m.status='pending' or (m.status='leased' and m.lease_until_ms<=now_ms and m.attempts<m.max_attempts))
              and not exists(select 1 from private.job_dependencies other join private.jobs p on p.id=other.prerequisite_id
                where other.job_id=m.id and p.id<>candidate.id and p.status<>'completed')
            order by m.id for update of m nowait
          ) x;
          if held is distinct from candidate.member_ids then
            raise exception 'dungeon settlement bundle changed' using errcode='PZ001';
          end if;
          picked:=picked||candidate.id||held;
        exception when lock_not_available or sqlstate 'PZ001' then
          -- Roll back all tentative row locks for this bundle. Other claimants can still take the reveal and its members.
          null;
        end;
        continue;
      end if;
      waits:='{}'::uuid[];
      if not candidate.ready then
        -- Only the reveals not already picked: one this claim took for an earlier settlement is locked by this transaction,
        -- was checked then, and precedes this settlement in the list.
        select coalesce(array_agg(p.id order by p.due_at_ms,p.id),'{}'::uuid[]) into waits from private.job_dependencies d
          join private.jobs p on p.id=d.prerequisite_id where d.job_id=candidate.id and p.status<>'completed' and p.id<>all(picked);
      end if;
      continue when cardinality(picked)+cardinality(waits)+1>cap;
      select j.id into settlement from private.jobs j where j.id=candidate.id and j.kind='settlement' and j.due_at_ms<=now_ms
        and (j.status='pending' or (j.status='leased' and j.lease_until_ms<=now_ms and j.attempts<j.max_attempts))
        for update skip locked;
      continue when settlement is null;
      if cardinality(waits)>0 then
        select coalesce(array_agg(x.id order by x.due_at_ms,x.id),'{}'::uuid[]) into held from (
          select p.id,p.due_at_ms from private.jobs p where p.id=any(waits) and p.kind='reveal' and p.due_at_ms<=now_ms
            and (p.status='pending' or (p.status='leased' and p.lease_until_ms<=now_ms and p.attempts<p.max_attempts))
            and private.dependencies_ready(p.id)
          for update skip locked) x;
        continue when cardinality(held)<>cardinality(waits);
      end if;
      picked:=picked||waits||settlement;
    end loop;
  end if;
  with chosen as (
    select x.id,x.ord from unnest(picked) with ordinality x(id,ord)
  ), previous as (
    select j.id,j.status as previous_status,j.attempts as previous_attempt from private.jobs j join chosen c on c.id=j.id
  ), expired as (
    update private.job_attempts a set finished_at_ms=now_ms,outcome='expired',failure_code='lease-expired'
    from previous p where p.previous_status='leased' and a.job_id=p.id and a.attempt=p.previous_attempt and a.outcome is null
  ), claimed as (
    update private.jobs j set status='leased',lease_token=gen_random_uuid(),lease_owner=claim_jobs.worker_id,leased_at_ms=now_ms,
      lease_until_ms=now_ms+120000,attempts=j.attempts+1
    from chosen c where j.id=c.id
    returning j.*,c.ord
  ), logged as (
    insert into private.job_attempts(job_id,attempt,worker_id,claimed_at_ms) select c.id,c.attempts,claim_jobs.worker_id,now_ms from claimed c
  )
  select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'token',c.lease_token,'expiresAtMs',c.lease_until_ms,'kind',c.kind,
    'activityId',c.activity_id,'gladiatorId',c.gladiator_id,'slotIndex',c.slot_index,'snapshot',c.input,'seed',c.seed,
    'rulesVersion',c.rules_version,'attempt',c.attempts) order by c.ord),'[]'::jsonb) into leases from claimed c;
  return leases;
end $function$;

CREATE OR REPLACE FUNCTION public.expedition_settlement_input (
  activity_id uuid,
  lease_token uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare result jsonb;
begin
  select jsonb_build_object('jobId',j.id,'state',o.state,'rewards',p.rewards,'rulesVersion',p.rules_version) into result
    from public.activities a join private.jobs j on j.dedupe_key='settlement:'||a.id
    join lateral (
      select e.plan->'rewards' as rewards,e.plan->'rulesVersion' as rules_version
        from private.expedition_plans e where a.resolved_kind='expedition' and e.activity_id=a.id
      union all
      select member.outcome->'rewards',d.plan->'rulesVersion'
        from private.dungeon_run_members m join private.dungeon_runs r using(run_id)
        join private.dungeon_results d using(run_id)
        cross join lateral jsonb_array_elements(d.plan->'outcomes') member(outcome)
        where a.resolved_kind='dungeon' and m.activity_id=a.id and r.slot_index=a.slot_index
          and r.dungeon_id=a.requested->>'dungeonId'
          and member.outcome->>'activityId'=a.id::text and member.outcome->>'gladiatorId'=a.gladiator_id::text
    ) p on true
    join public.gladiators g on g.id=a.gladiator_id
    join public.owner_state o on o.owner_id=g.owner_id
    where a.id=expedition_settlement_input.activity_id and j.lease_token=expedition_settlement_input.lease_token and j.status='leased'
      and j.lease_until_ms>private.planning_now_ms();
  return result;
end $function$;

CREATE OR REPLACE FUNCTION private.dungeon_rewards (
  activity uuid,
  prepared jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare a public.activities%rowtype; g public.gladiators%rowtype; p jsonb; applied jsonb; items jsonb:='[]'::jsonb; e jsonb; overflow jsonb; dungeon jsonb; member_outcome jsonb;
begin
  select * into a from public.activities where id=activity;
  select * into g from public.gladiators where id=a.gladiator_id;
  -- Only read shared frozen rows. The core already holds this member's account and settlement locks.
  select d.plan,member.outcome,jsonb_build_object('id',r.dungeon_id,'terminalFight',d.plan->'fights'->-1->'ordinal',
      'partyWon',d.plan->'fights'->-1->'won')
    into p,member_outcome,dungeon
    from private.dungeon_run_members m join private.dungeon_runs r using(run_id)
    join private.dungeon_results d using(run_id)
    cross join lateral jsonb_array_elements(d.plan->'outcomes') member(outcome)
    where m.activity_id=a.id and r.slot_index=a.slot_index and r.dungeon_id=a.requested->>'dungeonId'
      and member.outcome->>'activityId'=a.id::text and member.outcome->>'gladiatorId'=a.gladiator_id::text;
  if not found or a.resolved_kind is distinct from 'dungeon' or prepared->'rewards' is distinct from member_outcome->'rewards'
    then raise exception 'invalid dungeon preparation'; end if;
  if prepared->'progressionBaseline' is distinct from jsonb_build_object('level',g.level,'xp',g.xp) then return null; end if;
  if not private.safe_integer(prepared->'progression'->'level',1) or not private.safe_integer(prepared->'progression'->'xp') then raise exception 'invalid progression'; end if;
  applied:=private.apply_inventory_plan(g.id,prepared->'grant');
  if applied is null then return null; end if;
  update public.gladiators set level=(prepared->'progression'->>'level')::bigint,xp=(prepared->'progression'->>'xp')::bigint where id=g.id;
  update public.wallets set money=money+(member_outcome->'rewards'->>'money')::bigint+(applied->>'overflowMoney')::bigint where gladiator_id=g.id;
  for e in select * from jsonb_array_elements(prepared->'grant'->'plan'->'retained') loop
    items:=items||jsonb_build_array(jsonb_build_object('catalogId',e->'catalogId','catalogVersion',e->'catalogVersion','tier',e->'tier','rarity',e->'rarity','quantity',e->'quantity'));
  end loop;
  for e in select * from jsonb_array_elements(prepared->'grant'->'plan'->'stacked') loop
    items:=items||jsonb_build_array(jsonb_build_object('catalogId','salvage','catalogVersion',p->'catalogVersion','tier',1,'rarity','common','quantity',e->'quantity'));
  end loop;
  select coalesce(jsonb_agg(entry||jsonb_build_object('catalogVersion',p->'catalogVersion')),'[]'::jsonb) into overflow
    from jsonb_array_elements(applied->'overflow') entry;
  return jsonb_build_object('result',member_outcome->'result','success',member_outcome->'success','dungeon',dungeon,
    'rewards',jsonb_build_object('money',member_outcome->'rewards'->'money','xp',member_outcome->'rewards'->'xp','renown',0,'attributePoints',0,'items',items,'overflowMoney',applied->'overflowMoney','overflow',overflow),
    'replayExpiry',case when private.planning_now_ms()<a.ends_at_ms+604800000 then jsonb_build_object('state','available','expiresAtMs',a.ends_at_ms+604800000)
      else jsonb_build_object('state','expired') end);
end $function$;

CREATE OR REPLACE FUNCTION private.safe_settlement (
  value jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare r jsonb:=value->'rewards'; e jsonb; items jsonb:='[]'::jsonb; expiry jsonb; k text; result jsonb;
  overflow jsonb:='[]'::jsonb; total numeric:=0; dungeon jsonb:=value->'dungeon';
begin
  if jsonb_typeof(value) is distinct from 'object' or jsonb_typeof(r) is distinct from 'object'
    or coalesce(value->>'result','') not in ('completed','victory','defeat') or jsonb_typeof(value->'success') is distinct from 'boolean'
    or jsonb_typeof(r->'items') is distinct from 'array' then raise exception 'invalid settlement outcome'; end if;
  foreach k in array array['money','renown','xp','attributePoints','overflowMoney'] loop
    if not private.safe_integer(r->k) then raise exception 'invalid settlement outcome'; end if;
  end loop;
  for e in select * from jsonb_array_elements(r->'items') loop
    if jsonb_typeof(e) is distinct from 'object' or jsonb_typeof(e->'catalogId') is distinct from 'string'
      or jsonb_typeof(e->'catalogVersion') is distinct from 'string' or e->>'catalogId'='' or e->>'catalogVersion'=''
      or e->'tier' not in ('1'::jsonb,'5'::jsonb,'10'::jsonb) or e->'tier' is null
      or coalesce(e->>'rarity','') not in ('common','uncommon','rare') or not private.safe_integer(e->'quantity',1) then raise exception 'invalid settlement outcome'; end if;
    items:=items||jsonb_build_array(jsonb_build_object('catalogId',e->'catalogId','catalogVersion',e->'catalogVersion','tier',e->'tier','rarity',e->'rarity','quantity',e->'quantity'));
  end loop;
  if jsonb_typeof(value->'replayExpiry') is distinct from 'object' then raise exception 'invalid settlement outcome'; end if;
  if value->'replayExpiry'->>'state'='available' then
    if not private.safe_integer(value->'replayExpiry'->'expiresAtMs') then raise exception 'invalid settlement outcome'; end if;
    expiry:=jsonb_build_object('state','available','expiresAtMs',value->'replayExpiry'->'expiresAtMs');
  elsif value->'replayExpiry'->>'state'='expired' then expiry:=jsonb_build_object('state','expired');
  else raise exception 'invalid settlement outcome'; end if;
  result:=jsonb_build_object('result',value->'result','success',value->'success','replayExpiry',expiry,
    'rewards',jsonb_build_object('money',r->'money','renown',r->'renown','xp',r->'xp','attributePoints',r->'attributePoints','overflowMoney',r->'overflowMoney','items',items));
  if r ? 'overflow' then
    if jsonb_typeof(r->'overflow') is distinct from 'array' then raise exception 'invalid settlement outcome'; end if;
    for e in select * from jsonb_array_elements(r->'overflow') loop
      if jsonb_typeof(e) is distinct from 'object' or jsonb_typeof(e->'catalogId') is distinct from 'string'
        or jsonb_typeof(e->'catalogVersion') is distinct from 'string' or e->>'catalogId'='' or e->>'catalogVersion'=''
        or not private.safe_integer(e->'quantity',1) or not private.safe_integer(e->'unitValue') or not private.safe_integer(e->'money')
        then raise exception 'invalid settlement outcome'; end if;
      if (e->>'quantity')::numeric*(e->>'unitValue')::numeric<>(e->>'money')::numeric then raise exception 'invalid settlement outcome'; end if;
      total:=total+(e->>'money')::numeric;
      overflow:=overflow||jsonb_build_array(jsonb_build_object('catalogId',e->'catalogId','catalogVersion',e->'catalogVersion',
        'quantity',e->'quantity','unitValue',e->'unitValue','money',e->'money'));
    end loop;
    if total<>(r->>'overflowMoney')::numeric then raise exception 'invalid settlement outcome'; end if;
    result:=jsonb_set(result,'{rewards,overflow}',overflow);
  end if;
  if value ? 'ratingDelta' then
    if not private.safe_integer(value->'ratingDelta',-9007199254740991) then raise exception 'invalid settlement outcome'; end if;
    result:=result||jsonb_build_object('ratingDelta',value->'ratingDelta');
  end if;
  if value->>'arenaMode'='unranked' then result:=result||jsonb_build_object('arenaMode','unranked'); end if;
  if value ? 'dungeon' then
    if jsonb_typeof(dungeon) is distinct from 'object'
      or coalesce(dungeon->>'id','') not in ('wolf-den','raider-stronghold','troll-hall')
      or not coalesce(dungeon->'terminalFight' in ('1'::jsonb,'2'::jsonb,'3'::jsonb,'4'::jsonb),false)
      or jsonb_typeof(dungeon->'partyWon') is distinct from 'boolean' then raise exception 'invalid dungeon outcome'; end if;
    result:=result||jsonb_build_object('dungeon',jsonb_build_object('id',dungeon->'id',
      'terminalFight',dungeon->'terminalFight','partyWon',dungeon->'partyWon'));
  end if;
  return result;
end $function$;

-- SQL08 Arena hooks reached through the retained SQL10 settlement dispatcher.
CREATE OR REPLACE FUNCTION private.arena_settlement_failure (
  activity uuid
)
  RETURNS text
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare a public.activities%rowtype; seat private.arena_assignment_sides%rowtype; x private.arena_assignments%rowtype; o jsonb; live bigint;
begin
  select * into a from public.activities where id=activity;
  select * into seat from private.arena_assignment_sides where activity_id=activity;
  if not found then return 'arena-unassigned'; end if;
  select * into x from private.arena_assignments where battle_id=seat.battle_id;
  select r.outcomes->(seat.side::integer) into o from private.arena_results r where r.battle_id=seat.battle_id;
  if o is null or o->>'activityId' is distinct from a.id::text or o->>'gladiatorId' is distinct from a.gladiator_id::text then
    return 'arena-unsimulated';
  end if;
  if x.kind='bot' then return null; end if;
  select r.rating into live from private.arena_ratings r where r.gladiator_id=a.gladiator_id and r.league=x.league and r.season_index=x.season_index;
  if live is null or live is distinct from (x.assignment->'sides'->(seat.side::integer)->>'rating')::bigint
    or live is distinct from (o->>'ratingBefore')::bigint then
    return 'rating-mismatch';
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION private.arena_rewards (
  activity uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare a public.activities%rowtype; seat private.arena_assignment_sides%rowtype; x private.arena_assignments%rowtype; o jsonb;
  human boolean; won boolean; after bigint;
begin
  select * into a from public.activities where id=activity;
  select * into seat from private.arena_assignment_sides where activity_id=activity;
  select * into x from private.arena_assignments where battle_id=seat.battle_id;
  select r.outcomes->(seat.side::integer) into o from private.arena_results r where r.battle_id=seat.battle_id;
  if o is null or o->>'activityId' is distinct from a.id::text then raise exception 'missing arena outcome'; end if;
  human:=x.kind='human';
  won:=o->>'result'='victory';
  after:=(o->>'ratingAfter')::bigint;
  if x.kind<>'bot' then
    update private.arena_ratings set rating=after,
      human_wins=human_wins+case when human and won then 1 else 0 end,
      human_losses=human_losses+case when human and not won then 1 else 0 end
      where gladiator_id=a.gladiator_id and league=x.league and season_index=x.season_index;
    if not found then raise exception 'missing arena rating'; end if;
    update public.gladiators set rating=after where id=a.gladiator_id and league=x.league and rating is distinct from after;
  end if;
  update public.wallets set renown=renown+(o->'rewards'->>'renown')::bigint where gladiator_id=a.gladiator_id;
  insert into public.activity_stages(activity_id,ordinal,reveal_at_ms,stage) values(a.id,2,a.ends_at_ms,jsonb_build_object(
    'id',a.id::text||':2','kind','return','revealedAtMs',a.ends_at_ms,'startedAtMs',a.ends_at_ms,'endsAtMs',a.ends_at_ms,
    'label','Results credited'));
  return jsonb_build_object('rewards',o->'rewards','result',o->'result','success',o->'success','ratingDelta',o->'ratingDelta',
    'replayExpiry',case when private.planning_now_ms()<a.ends_at_ms+604800000
      then jsonb_build_object('state','available','expiresAtMs',a.ends_at_ms+604800000) else jsonb_build_object('state','expired') end)
    ||case when x.kind='bot' then jsonb_build_object('arenaMode','unranked') else '{}'::jsonb end;
end $function$;

CREATE OR REPLACE FUNCTION private.settle_activity_core (
  activity_id uuid,
  lease_token uuid,
  prepared    jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare a public.activities%rowtype; j private.jobs%rowtype; owner uuid; now_ms bigint; receipt uuid:=gen_random_uuid();
  settlement jsonb; operation uuid:=gen_random_uuid(); result_summary jsonb; outcome jsonb; inserted integer; failure text; grant_id text;
  bot_activity boolean;
begin
  if settle_activity_core.activity_id is null or settle_activity_core.lease_token is null then return jsonb_build_object('ok',false,'code','invalid'); end if;
  select g.owner_id into owner from public.activities x join public.gladiators g on g.id=x.gladiator_id where x.id=settle_activity_core.activity_id;
  if not found then return jsonb_build_object('ok',false,'code','not-found'); end if;
  perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
  perform 1 from public.gladiators g join public.activities x on x.gladiator_id=g.id where x.id=settle_activity_core.activity_id for update of g;
  perform 1 from public.wallets w join public.activities x on x.gladiator_id=w.gladiator_id where x.id=settle_activity_core.activity_id for update of w;
  perform 1 from public.item_instances i join public.activities x on x.gladiator_id=i.gladiator_id where x.id=settle_activity_core.activity_id order by i.id for update of i;
  perform 1 from private.arena_ratings r join private.arena_assignment_sides s on s.activity_id=settle_activity_core.activity_id
    join private.arena_assignments x on x.battle_id=s.battle_id join public.activities y on y.id=s.activity_id
    where x.kind<>'bot' and r.gladiator_id=y.gladiator_id and r.league=x.league and r.season_index=x.season_index for update of r;
  perform 1 from private.arena_ratings r join private.tournament_entries e on e.activity_id=settle_activity_core.activity_id
    join private.tournaments t on t.id=e.tournament_id
    where r.gladiator_id=e.gladiator_id and r.league=t.league and r.season_index=t.season_index for update of r;
  select * into a from public.activities where id=settle_activity_core.activity_id for update;
  select * into j from private.jobs where dedupe_key='settlement:'||a.id for update;
  if not found then return jsonb_build_object('ok',false,'code','not-found'); end if;
  now_ms:=private.planning_now_ms();
  if j.status='completed' then
    -- A lost response retries with the same token and receives the committed receipt, never a second grant.
    if j.lease_token=settle_activity_core.lease_token then return j.result||jsonb_build_object('newGrants',0,'replayed',true); end if;
    return jsonb_build_object('ok',false,'code','conflict');
  end if;
  if j.status<>'leased' or j.lease_token is distinct from settle_activity_core.lease_token or j.lease_until_ms<=now_ms then
    return jsonb_build_object('ok',false,'code','conflict');
  end if;
  if a.status<>'active' or now_ms<a.ends_at_ms then return jsonb_build_object('ok',false,'code','processing'); end if;
  if not private.dependencies_ready(j.id) or a.slot_index>coalesce((select published_slot from private.coordinator where singleton),-1)
    or exists(select 1 from public.activities earlier where earlier.slot_index<a.slot_index and earlier.status<>'completed') then
    return jsonb_build_object('ok',false,'code','processing'); end if;
  bot_activity:=exists(select 1 from private.activity_snapshots s where s.activity_id=a.id and s.snapshot ? 'botDirective');
  if not bot_activity and a.resolved_kind in ('arena','tournament')
    and not exists(select 1 from private.settled_slots s where s.gladiator_id=a.gladiator_id and s.slot_index=a.slot_index) then
    if a.resolved_kind='arena' then failure:=private.arena_settlement_failure(a.id); else failure:=private.tournament_settlement_failure(a.id); end if;
    if failure is not null then
      -- Fail closed before any grant or checkpoint: neither the frozen nor the live value is used.
      update private.jobs set status='operator',lease_token=null,lease_owner=null,lease_until_ms=null,last_failure=failure where id=j.id;
      update private.job_attempts set finished_at_ms=now_ms,outcome='failed',failure_code=failure where job_attempts.job_id=j.id and attempt=j.attempts;
      return jsonb_build_object('ok',false,'code','operator');
    end if;
  end if;
  insert into private.settled_slots(gladiator_id,slot_index,activity_id,receipt_id,resolved_kind,settled_at_ms)
    values(a.gladiator_id,a.slot_index,a.id,receipt,a.resolved_kind,now_ms) on conflict do nothing;
  get diagnostics inserted=row_count;
  if inserted=0 then
    -- The permanent checkpoint already exists: finish the job with that receipt and grant nothing.
    select s.receipt_id into receipt from private.settled_slots s where s.gladiator_id=a.gladiator_id and s.slot_index=a.slot_index;
    outcome:=jsonb_build_object('ok',true,'activityId',a.id,'newGrants',0,'replayed',true)
      ||case when bot_activity then '{}'::jsonb else jsonb_build_object('receiptId',receipt) end;
  elsif bot_activity then
    -- Keep the permanent activity history for Training caps and recover ordinary Rest. Publish no grant or result.
    if a.resolved_kind='rest' then
      update public.gladiators set stamina_current=stamina_maximum where id=a.gladiator_id;
    end if;
    update public.activities set status='completed',settled_at_ms=now_ms where id=a.id;
    outcome:=jsonb_build_object('ok',true,'activityId',a.id,'newGrants',0);
  else
    if a.resolved_kind in ('expedition','dungeon') then
      if a.resolved_kind='dungeon' then settlement:=private.dungeon_rewards(a.id,prepared);
      else settlement:=private.expedition_rewards(a.id,prepared); end if;
      if settlement is null then
        -- Raise in a subtransaction at the RPC wrapper: every tentative write/guard rolls back before stale return.
        raise exception 'stale preparation' using errcode='P0002';
      end if;
    else settlement:=private.settle_rewards(a.id); end if;
    if a.resolved_kind='tournament' then
      -- Exception 7: the placement grant's one identity, kept with this activity's receipt; the summary whitelist drops it.
      grant_id:=settlement->'placement'->>'id';
      if grant_id is null then raise exception 'missing placement grant'; end if;
    end if;
    settlement:=private.safe_settlement(settlement);
    result_summary:=settlement||jsonb_build_object('activityId',a.id,'resolvedKind',a.resolved_kind,'receiptId',receipt,'settledAtMs',now_ms);
    if a.resolved_kind in ('expedition','arena','tournament','dungeon') then
      insert into public.operation_receipts(owner_id,operation_id,receipt_id,gladiator_id,request,request_digest,result)
        values(owner,operation,receipt,a.gladiator_id,jsonb_build_object('kind','activity-settlement','activityId',a.id)
          ||case when grant_id is null then '{}'::jsonb else jsonb_build_object('grantId',grant_id) end,
          extensions.digest(a.id::text,'sha256'),result_summary);
      insert into public.wallet_ledger(gladiator_id,receipt_id,money_delta,renown_delta,reason)
        values(a.gladiator_id,receipt,(settlement->'rewards'->>'money')::bigint+(settlement->'rewards'->>'overflowMoney')::bigint,
          (settlement->'rewards'->>'renown')::bigint,a.resolved_kind);
    end if;
    update public.activities set status='completed',receipt_id=receipt,summary=result_summary,settled_at_ms=now_ms where id=a.id;
    outcome:=jsonb_build_object('ok',true,'activityId',a.id,'receiptId',receipt,'newGrants',1,'summary',result_summary);
  end if;
  update private.jobs set status='completed',result=outcome,completed_at_ms=now_ms where id=j.id;
  update private.job_attempts set finished_at_ms=now_ms,outcome='completed' where job_attempts.job_id=j.id and attempt=j.attempts;
  return outcome;
end $function$;

