    {"id":"pathfinder","measure":"expeditions-won","threshold":50,"tier":2},
    {"id":"trailblazer","measure":"expeditions-won","threshold":200,"tier":3},
    {"id":"wolfbane","measure":"woodland-won","threshold":25,"tier":null},
